// 自动生成：node scripts/v2-extract.mjs。请勿手改，改阅读稿后重新生成。
export const SCENES={"M01":{"id":"M01","title":"养心惊梦","kind":"main","actor":"C02","location":"养心殿御案","body":"痛意先从胸口褪去，接着是病榻旁那股散不尽的药味。\n\n你猛然睁眼，指尖碰翻了案上的笔。朱砂洇过折角，像一小片未干的血。窗外没有送终的钟，只有雪粒扑打窗纸的细响。\n\n“皇上？”\n\n苏培盛掀开半幅帘，抱着拂尘站在门边。他还没有记忆里那样苍老，听见响动却一样先看你的手，怕你碰伤，又不敢贸然上前。\n\n你低头看折上的年款：雍正元年。\n\n那一年，西北的捷报还未送完，翊坤宫的香尚未停。许多后来再也无法挽回的人，此刻都还在。你想叫他的名字，喉间却像仍堵着最后那口药。\n\n“可是又魇着了？奴才这就去传太医。”\n\n他转身前，先将帘钩放轻。那个小动作让你想起，从前惊醒时，他总先把一切安排好，等天亮便又隐进值守的人群；你甚至没问过他一夜能睡多久。\n\n苏培盛见你没有应声，手停在帘边。传人怕惊动你，退下又怕你独自在里头。他往前半步，仍等你发话。\n\n上一世，你总有更急的折子，觉得一句话来日再说也无妨。眼下笔还握在手里，门也尚未关上。\n\n案旁的烛花爆了一声。他轻声再问：“皇上，奴才该怎么伺候？”","options":[{"id":"steady","label":"把灯留下，先缓一缓","effects":{"mood":4},"bonds":{},"slight":null,"reply":"你把掌心压在温热的茶盏上，慢慢松开蜷紧的指节。\n\n“不必传人。把灯拨亮些。”\n\n苏培盛应了一声，将最亮的灯挪到你手边，又撤开被朱砂弄湿的折子。你尚不愿说的，他没有追问。\n\n“奴才在外头。皇上若再醒，叫一声就是。”\n\n隔着帘，你听见他搬近椅子的轻响。你终于能看清年款，也能把这一口气慢慢喘匀；惊醒的缘故，仍只留在自己心里。"},{"id":"verify","label":"问清年款，再问故人的近况","effects":{"execution":2},"bonds":{},"slight":null,"reply":"“今年是哪一年？”\n\n苏培盛脸色微变，先看你手里的折子：“回皇上，雍正元年。张大人的折子是今早递进来的。”\n\n你又问过几个人的近况。他逐一作答，怕漏掉什么，索性取纸记下。那些名字后面，没有一个跟着噩耗。\n\n“好。”你说得很轻。\n\n他听不懂这个好字，只将纸压在案边：“有哪处还要问，奴才再去核。”眼前有了可对照的人与事，你没有急着把旧梦说成今日的实情。"},{"id":"call","label":"“苏培盛，过来。”","effects":{"mood":2},"bonds":{},"slight":null,"reply":"“苏培盛，过来。”\n\n他立刻进帘，原以为你要问值守，却见你望了他许久。久到他摸摸袖口，疑心茶水是不是溅湿了衣裳。\n\n“今夜也是你？”\n\n“奴才在，皇上放心。”还是那句说惯了的话。\n\n你将案侧的折子挪开一点，够他搁下拂尘。他迟疑着站近，见你没有别的吩咐，便先把翻倒的笔收好。\n\n“那奴才就在这儿候着。”他的声音低下来。今夜你叫住了一个人，尚不必立刻找出留他的理由。"}]},"M02":{"id":"M02","title":"留茶夜谈","kind":"main","actor":"C02","location":"养心殿御案","body":"更漏过了三声，案头的折子终于薄下去。\n\n苏培盛换过一回茶，见你没有再翻折，便把凉透的杯盏收进盘中。他做事几乎没有声音，连退出帘子前的停顿，都与你记忆里一样。\n\n“明日还得早朝。皇上也该歇了。”\n\n你问他什么时候交班。他先报值宿的人名，末了才说自己还要守后半夜：“白日里眯过一会儿，不妨事。”话音刚落，他低低咳了一声，立刻偏过脸。\n\n你伸手要名册。他将册角按住，解释值房有两处缺人，新来的又不熟更次。说到最后，仍想把自己的名字填进去。\n\n“总不能叫御前误事。”\n\n他怕你一句体谅落下，门外却没有人接更；也怕自己多说两句，倒像拿辛劳讨赏。那支笔停在纸上，迟迟没有落。\n\n桌上还有一只没用过的白瓷杯。你知道这人记得你何时要热茶、何时要静，却想不起他平日喜欢喝什么。\n\n“你喝茶么？”\n\n“皇上若要，奴才再去沏。”他答得太快，才发觉问的似乎不是这件事。\n\n窗外换更的脚步渐近。他握着茶盘，等你决定这片刻究竟留给闲话，还是留给那页尚未填完的册子。","options":[{"id":"tea","label":"把另一只杯子推给他","effects":{"mood":2},"bonds":{},"slight":null,"reply":"你取过白瓷杯，倒半杯温茶，推到案边。\n\n“给奴才的？”苏培盛的手还停在茶盘上。\n\n“说说你白日里都忙些什么。”\n\n他迟疑片刻，端起杯子。头一口很小，第二口才慢下来，渐渐说起值房里那只总找不到的铜手炉。\n\n门外换更声过去了。他看了一眼名册，没再抢着补上自己的名字。今夜先有人听他把闲话讲完；册上缺的更次仍夹着纸签，不能靠这一盏茶就填平。"},{"id":"duty","label":"翻开交接册，问问他的值守","effects":{"execution":1},"bonds":{},"slight":null,"reply":"你没有拦他收盏，只把交接名册翻到最后一页。\n\n“这里怎么又是你的名字？”\n\n苏培盛原想说习惯如此。你将笔搁在空行旁，等他把缺人和带教的难处讲完。\n\n“那便把缺的写清。”\n\n他终于划开一小格，照实写下待接的更次，没有替谁把缺口遮过去。册子尚待经办，今夜却少了一句含混的“不妨事”。他收起笔：“奴才明日就照这一页呈，不另换一本好看的。”"},{"id":"rest","label":"“交班以后，今夜好好睡。”","effects":{"health":1,"mood":1},"bonds":{},"slight":null,"reply":"“交过班就去歇着，别又替人守到天亮。”\n\n苏培盛看向名册，指尖在接更人的名字上停住：“等小夏来，奴才把要紧的交代清。”\n\n你没有让他立刻丢下茶盘，只说：“明早朕还要问你睡得怎样。”\n\n他露出一点无奈的笑，先将需交代的几件事另写出来。出门时少收了一只杯，又折回来取。\n\n“这回记得。”他说。话已说到这里，真正能否按时歇下，还得有接班的人把那几件事接过去。"}]},"M03":{"id":"M03","title":"停香无声","kind":"main","actor":"C07","location":"翊坤宫","body":"颂芝呈上香料领用单，那个熟悉的香名让你的笔停住。\n\n翊坤宫里，年世兰正拨开香灰，见你进来便笑：“皇上来得巧，新换的香才点上。”她将炉盖推开一些，要你也闻闻。\n\n你抬手拦住。她的笑意慢慢收住，目光从你的手移到香炉。\n\n“怎么了？这香不是一直用着么？”\n\n上一世的药气忽然翻上来。你记得她后来问过多少次，又有多少句解释迟得再也无用。但案前只有今日的领用单，尚没有一份能核清香料的回报。\n\n年世兰等了一会儿，自己把香匙搁下。颂芝端着新盒，不知该进还是该退。\n\n“要换便换。”她说得硬，“只是臣妾用了这些年，皇上总得告诉臣妾，是嫌气味，还是另有什么事。”\n\n她原想留你说几句近来的起居，眼下却像连自己屋里这一缕烟都作不得主。你看见她袖口绷紧，才明白一句“为你好”也可能又把她挡在门外。\n\n炉口还有细烟。年世兰伸手去碰炉盖，又在半途停下。颂芝抱着两只香盒等着，谁也不敢先将旧的收走。她没有再笑，等你答方才那句为什么。","options":[{"id":"sample","label":"停供留样，请太医院核验","effects":{"treasury":-2,"health":2,"palace":2},"bonds":{},"slight":null,"reply":"你亲手合上香炉，请颂芝将余香与领用单一并封存，交太医院核验。\n\n年世兰盯着炉盖：“太医也要来？”\n\n“来。哪里不舒服，都照实说。”\n\n她叫住颂芝，把近日夜里难眠的几回逐一报出，又要自己留一份单子。烟停了，她却没有立即安心：“查到什么，别只叫人回一句无妨。”\n\n你应下这句。眼前先停了继续使用，待核的疑处仍在纸上；她想问的缘由，也还等你慢慢说清。"},{"id":"explain","label":"先说明疑虑，再安排停供","effects":{"treasury":-2,"palace":3},"bonds":{},"slight":null,"reply":"你在她身旁坐下，先说这香有待核的疑处，今日的领用与用后情形须一同查，并没有已查明的结论。\n\n年世兰几次想插话，见你没避开目光，终究听到最后。\n\n“那便先停。”她自己将炉盖合好，让颂芝把旧香依领用单封好，另留一份单子：“这盒也别扔。”\n\n她又问还有哪些尚不清楚，问得比方才慢。茶仍凉在案上，她已取过领用单，亲自核过一遍。此次留下了她能追问的凭据，没有用一句安心替她收尾。"},{"id":"quiet","label":"暗中换去香料，暂不说明","effects":{"treasury":-1,"palace":-2},"bonds":{},"slight":null,"reply":"你只说另换一味，让人撤下旧香，暂未讲明疑处。\n\n年世兰看着香盒被收走：“皇上今日，怎么忽然想起这个？”\n\n你没有接着解释。她应了一声，转身添茶，壶嘴碰到杯沿，响得比平日重。\n\n“颂芝，把今日换过什么记下。”\n\n旧香已停，眼前的烟散了。她却将那只新杯留在桌上，没有再叫你闻香。她自己记下了变化，仍不知道你为何这样做；这份疏离，不能当成疑虑已经说开。\n\n出门后，你另外交代将旧香封好留样，连领用单送太医院核对。样留下了，疑处仍未向她说明；核对有了交办，也没有因此变成她已听过的解释。"}]},"M04":{"id":"M04","title":"新帝第一折","kind":"main","actor":"C28","location":"养心殿御案","body":"张廷玉把地方库银册与西北催粮折并排放下，指间还沾着未干的墨。\n\n“两处都在催。若一并限期，县里恐怕只能再摊下去。”\n\n你翻到一页旧欠，秋粮数改过三次，末尾却盖着同一方印。旁边夹着米价单：同样一笔缺口，在这本册里是数，在县里便得有人卖粮补上。\n\n门外的书吏抱着副册等候，衣摆湿了一圈。张廷玉没有替他求快，只将能核的经手名目压到案前。\n\n“原簿要几日？”\n\n“得等下一批递报。眼前种粮周转，却等不得。”\n\n他想先把钱确实经过谁的手查清，也怕一句缓办，让地方继续把旧账往后推。催粮折上的急字还未干，谁也不能靠一句都要顾到，让两边的缺口同时消失。\n\n你将两册挪开一点。今日能定的是如何先腾挪、催到多紧、从哪一笔查起；粮有没有进县仓，银有没有被转摊，仍要看后面送来的原簿。\n\n张廷玉执笔等着，没把任何一个县名先划去。","options":[{"id":"balance","label":"先保周转，分期清账","effects":{"treasury":-3,"people":3},"bonds":{},"slight":null,"reply":"你在周转项旁留下批注：先留出种粮所需，旧欠分期核清。\n\n张廷玉问过留用的数，才将地方库册与催粮折分开。他指向一笔被改过的秋粮：“这一处，臣仍要取原簿。”\n\n你点头，让他把限期和经手写明，免得缓办传到下面又变了说法。\n\n他收折时少压了一层纸，先把周转凭据带走。库里为此先让出三点，县里的明日却有了可用的余地；后面的清账，还得逐笔办。"},{"id":"quick","label":"限期清缴，先稳国库","effects":{"treasury":3,"people":-3},"bonds":{},"slight":null,"reply":"期限落定，张廷玉逐一圈出催缴的县名，将能先回的三点暂款列入眼前周转。\n\n“先记这一笔，不把它算作旧欠全清。”他说。\n\n你核过数目，他又把米价单夹回副册：“臣会另核催到下面，究竟向谁收了。”\n\n折子送出门，案上的急用有了三点来处。那些被圈住的县名却没有一并消失；你催得越紧，下一次回报里就越不能漏看摊派与粮价。张廷玉将那页留在最上头。"},{"id":"audit","label":"先查大户与经手人","effects":{"treasury":-1,"execution":3},"bonds":{},"slight":null,"reply":"你点出改动最密的几笔，先查大户旧欠与经手签押，拨一点给核查周转。\n\n张廷玉没有当即圈定谁有罪，取来空纸，把原页、押名和待取的副册分列开。\n\n“先从这几个人经手处往前问。”\n\n门外书吏被请进来，照纸上的日期逐项作答。你听见一个原来挤成总数的缺口，终于拆成了能追问的几笔。催粮折仍在旁边，眼前回款不会因此立刻增多；这一次，查问至少有了具体去处。"}]},"M05":{"id":"M05","title":"景仁赠环","kind":"main","actor":"C06","location":"景仁宫","body":"宜修将玉环托在掌心，没有立刻戴上。\n\n“皇上还记得它。”她说。\n\n灯下那道温润的光，与多年前几乎一样。你记得当年挑玉的铺陈，也记得后来许多次来景仁宫，总是先问事，再留一句改日来坐。\n\n宜修等了一会儿，把玉放回帕上。案头一摞宫账齐整，最上面露出半张纸签，像早已预备好今日仍只谈宫务。\n\n“皇上今日来，是想问这几本册子，还是想说些别的？”\n\n语气平稳，手却没有离开那块帕。她想知道这次来意能落在哪一处，又不愿先把一枚玉环当成许诺，日后只剩自己记得。\n\n你坐到案边空位。她将茶推近些，问你要浓还是淡，话到这里便停了，不替你把亲近的缘由接下去。\n\n册子里有几处久拖的签核，玉也确实是为她留下的。宜修将两样都留在案上，没有先戴玉，也没有替你打开账册。她想听的那句来意，终究得由你自己说。\n\n宜修没有催你。杯盖轻轻落稳，她终于抬眼，等你亲口答这句来意。","options":[{"id":"rights","label":"先谈中宫权责","effects":{"palace":3},"bonds":{},"slight":null,"reply":"你先将宫账挪到两人之间：“哪几处最难办，你说给朕听。”\n\n宜修停了一瞬，才抽出那张纸签，指出领差与签核分在两处，出了差错却都来问她。\n\n你没有用赠玉岔开，逐条问她需要怎样的权责。她越说越清楚，原来早备好的几句客套，反倒没有用上。\n\n玉仍放在帕上。今晚她先得到一次把难处讲完整的机会；哪些事正式交给谁，仍须往后核定。她将那张纸签留下，没有收回袖中。"},{"id":"visit","label":"提出定期相见，再核对日程","effects":{"mood":2},"bonds":{},"slight":null,"reply":"“往后想常来坐坐。”你说。\n\n宜修看过玉环，嘴边浮起一点笑，又问：“便是没什么好听的话，也来么？”\n\n你答愿意听。她这才重新拿起玉，慢慢转过内沿：“臣妾有空时，也想把这些册子先合上。”\n\n她没有立即报一个日子，你也未替两人把约期写定。茶盖揭开，这一回你们先说了几句各自想怎样度过闲时。她听见了来意，是否、何时再见，还可以认真商量。"},{"id":"gift","label":"先留下玉环，不逼她回应","effects":{"mood":1},"bonds":{},"slight":null,"reply":"你将玉留在她掌边，没有催她戴，也未拿常来相见的话填满沉默。\n\n宜修拢好帕角：“那臣妾先收着。”\n\n她问你要不要添茶，又把那张露出的纸签压回账页。杯盖掀开时热气尚在，你坐着喝完，才起身。\n\n玉匣没有被立刻打开，宫务也未借此得到新批示。临走，她依礼送到门边，神情比先前安稳一些。这份东西被收下了，至于礼物之外的意思，今日没有人替另一个人认定。"}]},"M06":{"id":"M06","title":"殿前择人","kind":"main","actor":"C08","location":"宫宴大殿","body":"宫门外的风吹乱了衣角。殿前几个人依次报姓名，声音或稳或颤，落在空阔的殿里。\n\n安陵容的鞋尖沾了一点泥，往后退时悄悄藏了藏。沈眉庄略侧身，替她挡过旁人的一瞥，又站回自己的位置。甄嬛抬头答问，答到家中教养时，没有借旁人的话替自己添上一层。\n\n太后轻叩杯盖：“皇帝，可有话问她们？”\n\n你握着名册。许多旧日面孔与眼前重叠，又慢慢分开。她们尚未说过、做过的那些事，此刻都不能拿来作评语。\n\n掌册宫人先要按家世另排几页，你的手停在名册上，他便不敢继续。安陵容看见那一下停笔，原想说会唱曲，终于又咽回去；沈眉庄抬了抬眼，等听清宫里究竟按什么办。甄嬛也没有再笑，只把答过的那句留住。\n\n名单上的身份已定。今日问什么、怎样记、份例按什么给，却会成为她们进门后先遇到的规矩。\n\n太后将杯盖放稳：“想问便问，时辰还够。”掌册的人重新蘸墨。几个人仍站在各自的位置，等着第一句究竟是问家中，还是问她们自己。\n\n这场接见散后，若还想各留一句私话，可分别说清；不想此时开口，也可让今日先停在礼数上。","options":[{"id":"fair","label":"按位分给足份例","effects":{"treasury":-2,"palace":3},"bonds":{},"slight":null,"reply":"你让宫人照位分核清份例，不因谁家势薄便短下一项，拨出相应用度。\n\n掌册的人翻回同一页，将原先另夹的几张纸合在一处。安陵容抬头看了一眼，沈眉庄轻轻碰过她的袖口，两个人才站稳些。\n\n甄嬛问了一句：“往后若与册上不符，也可依这份问么？”\n\n你让她按册呈问。她依礼谢过，没有替旁人求额外一份。两点用度有了去处，眼下的礼遇也有了共同的依据；往后是否照办，仍得有人看着。"},{"id":"ability","label":"逐一询问所长","effects":{"execution":2},"bonds":{},"slight":null,"reply":"你依次问她们所长，听完一人，再问下一人。\n\n沈眉庄说起读书，甄嬛接了自己的答话；轮到安陵容，她起初说没什么，望见落笔的人仍在等，才小声补了一句会唱。\n\n“那便记上。”\n\n墨落在各人的名下，不再只有家世。安陵容退下时，目光还留在那一行字上。沈眉庄没有替她代答，甄嬛也把余下的话收住。今日每人都亲口留下了一件自己的事，谁也尚未因此被安排成谁的心腹。"},{"id":"brief","label":"殿前依礼接见，不加私问","effects":{"palace":1},"bonds":{},"slight":null,"reply":"你依礼问过起居与家中，殿前不另加问私事。\n\n掌册宫人等到最后一个名字报完，才将名册合起。甄嬛向太后与御前分别行礼，沈眉庄走在安陵容身侧，到了门槛处放慢半步。\n\n殿外的风迎面吹来，安陵容终于松开一直攥住的帕。没有额外恩许，也没有因答得不够响亮便受斥。\n\n你看着三人依次出门。今日把接见完整走完，往后的相识还留着余地；这一段礼数，没有被谁擅自写成私下的允诺。"}]},"M07":{"id":"M07","title":"宫宴微澜","kind":"main","actor":"C08","location":"宫宴大殿","body":"安陵容的曲子唱到一半，席间落下一句关于出身的笑话。\n\n弦还在响，她的声音却停了。举杯的人没放杯，说笑的人也在等，看这一句会不会就这样过去。\n\n宜修转头望你，手已按在席单上。年世兰放下箸，没有接那声笑。安陵容低头攥帕，嘴唇动了动，像想把剩下半句接回去，却怕再唱只会惹来更多议论。\n\n“还唱么？”掌乐的人轻轻问她。\n\n她抬头，先看那架尚未收起的琴，才低声道：“末句还没有完。”\n\n你想起第一次见她时，那双努力藏住泥痕的鞋。今夜若只添一份赏，曲子会被赏物盖过去；若当众替她把一切都说完，她自己的后半句又将放在哪里。\n\n宜修等你示意，也有她须主持的席间礼数。你若请她处置，她得能真正说话；若自己开口，满席的人也会记住是谁压住了这场难堪。\n\n你将杯搁在桌上。声音不重，近处的人却都听见了。安陵容没有退席，仍握着那半句曲，等着一个能继续唱下去的间隙。","options":[{"id":"queen","label":"请皇后依规纠偏","effects":{"palace":3},"bonds":{},"slight":null,"reply":"你看向宜修，请她依席间礼数处置。\n\n她叫停那句话，向说笑的人问清，又让掌乐等安陵容自己起调。满席的人这回听见的，是皇后把规矩说完整。\n\n安陵容握稳帕角，朝琴边点了点头，接回末句。第一声仍轻，到收尾已不再颤。\n\n曲终，宜修将席单放回案上，你轻轻颔首。没有再拿她的家世续一轮笑，也没有替她许诺往后件件都由御前出面。今夜的曲，是她自己唱完的。"},{"id":"skill","label":"让她把曲子唱完","effects":{"mood":3},"bonds":{},"slight":null,"reply":"“曲还没完。”你说，“你若愿意，朕还想听末句。”\n\n安陵容看向掌乐的人，点头示意接弦。第一句仍颤，第二句慢慢稳住，最后一转竟比开头清楚。\n\n你问的只是那一转为何这样唱。她答是原谱里喜欢的一处，说完才发现席间已有人认真听她答曲。\n\n笑话被截住，难堪却不会凭这一刻全散。她下席前先朝琴边致意，再向你行礼。今夜留在众人耳里的，终于还有她真正唱出的本领。"},{"id":"stop","label":"当场制止讥讽","effects":{"palace":1,"stability":-1},"bonds":{},"slight":null,"reply":"你放下杯，直说那句话不该出现在席上。\n\n说笑的人起身请罪，几处交谈同时静下。宜修收住席单，待你说完，才示意掌乐重新候着。\n\n你问安陵容愿不愿继续。她慢慢松开帕角，答还有末句，便自己接了回去。\n\n你的态度足够鲜明，席间也冷了片刻；这一场如何收住，仍要顾及在座的人。曲终她谢过，没有借此再告旁人的不是。你看着她走回座位，终于不必低头躲那声笑。"}]},"M08":{"id":"M08","title":"雨廊赠衣","kind":"main","actor":"C04","location":"宫门长廊","body":"雨水沿廊檐落下来，石阶亮得像镜面。温实初抱着药箱候在门外，衣袖湿到手腕。\n\n“等多久了？”\n\n他先行礼，说脉案已核过，才答没多久。药箱上的漆色被雨打深，你看见他将两张纸护在最里层，自己肩头却没有遮。\n\n“先进去避雨。”\n\n他下意识望向值门的人，等你侧身让出路，才跨过门槛。纸放到案上，两处字旁有细小的圈，另有一页被他压在掌下。\n\n你问那是什么。他说是还须复诊的地方：“今日能回的，臣都写清了。没核准的，想等再问过，才敢落定。”\n\n他想保住这点不把话说满的余地，怕御前嫌迟，又怕你见他衣湿便只问辛劳，反把真正要呈的医事搁过。\n\n窗外的雨还未收。他的手终于离开那页纸，却仍先将药箱挪到干处。值门的人送来干帕，他伸手去接，湿衣在腕边贴出深深的折痕，又很快把手收回，怕误了你问话。\n\n温实初在案边站定，等你问第一句。","options":[{"id":"listen","label":"问他真正想做的医事","effects":{"execution":2},"bonds":{},"slight":null,"reply":"你问他护在箱里的那页，究竟最想查清什么。\n\n温实初先答症候，又顿了顿，说起有些复诊记录太短，病人上回没说完的话，下回便像没发生过。\n\n你让他把那两处圈点讲完。他不再先赔一句医术浅陋，顺着纸页，把自己为何留意那里说清。\n\n雨渐渐小了，他仍没察觉。桌上多了一段能问下去的医事，尚没有因此就查明所有病因。收纸时，他特意把未核的那页另放，眼神比入门时安定。"},{"id":"medical","label":"只核对脉案，守住医职边界","effects":{"health":3},"bonds":{},"slight":null,"reply":"你请他只按脉案，把已核与待复诊处分别说明。\n\n温实初点头，先将那页尚未落定的纸放在一旁，再逐行答你。你照他说的复述一遍，他指正一处容易混淆的说法，没有因你在御前便顺着认下。\n\n最要紧的一行被圈出来，你也记清了往后何时该问医。\n\n雨声仍在，他没有被留着另讲心事。你把干帕推到案边，他道谢擦过袖口，带着整理好的脉案告退。这一趟，医者的话被完整听清。"},{"id":"rain","label":"先让他避雨，再安排问诊","effects":{"treasury":-1,"health":2},"bonds":{},"slight":null,"reply":"你先让人取干衣与热茶，问诊稍候，药箱留在干处。\n\n温实初还想递那页纸，你指指他滴水的袖口。他这才停手，谢过出去换衣，回来时仍把脉案抱在胸前。\n\n“如今可以回了。”他声音暖了些。\n\n你让他坐近灯，一项项说明。那一点用度先落在干衣和茶水上，没有换成要他报答的心事。临走，他主动检查窗边是否漏雨，再将两页纸收好；这回湿的是箱角，字迹终于都保住了。"}]},"M09":{"id":"M09","title":"御园笛声","kind":"main","actor":"C05","location":"御花园","body":"园中笛声转过一折，在水面上慢慢散开。你停下脚步，随行的人也停了。\n\n允礼从树影里望过来，收笛起身行礼。袍角落着两片花，他顾着礼数，还没来得及拂。\n\n“臣弟办完差事，借这地方试一页旧谱。惊扰皇兄了？”\n\n你摇头。他便把谱展开，指尖停在一个涂改的音旁，像还舍不得将方才的半曲收回去。园门外有人候着帖子，他看一眼日影，先说明午后还须回府。\n\n“这一处，臣弟改过，也未必就比原谱好。”他笑道，“若只奏给人听个吉祥，倒不必费这个劲。”\n\n你记得这个人后来被写进多少人的旧事，眼前他却只是想把自己听见的半拍试完。你望向谱页，他没有先问御前喜欢哪一种，也没有急着将改处抹去。\n\n帖子还压在石案一角。他将它往旁边挪挪，腾出摊谱的地方，又告诉候着的人，到了时辰就来提醒，不必因御前在此便一直等。\n\n允礼将笛在掌中转正：“皇兄想听哪一段？”","options":[{"id":"music","label":"谈这一段笛谱","effects":{"mood":3},"bonds":{},"slight":null,"reply":"你问他涂改处为什么多停半拍。\n\n允礼先试原谱，再奏自己的改法，让你听两处不同。你说后者像多留了一口气，他笑起来：“皇兄听得仔细，臣弟却还想再试。”\n\n他没有顺势把谱改成你喜欢的那种，反将两种写法并排留下。\n\n日影移过石案，帖子仍压在角上。这一曲有了能认真争论的人，也仍有各自的时辰；他把那页折好，没有许下一句随召随到。"},{"id":"duty","label":"先问宗室差事与王府近况","effects":{"stability":2},"bonds":{},"slight":null,"reply":"你先问今日差事与王府近况，允礼将帖子递到案边，指着两处经手说清。\n\n他不因在园中闲坐便含混带过，也没把待回府核的那一桩说成办完。你问到哪里，他便翻到原页，最后仍将未核处留着。\n\n公事说完，他收起帖子，望一眼尚在手边的笛：“这下，臣弟可以把那曲奏完了？”\n\n你让出石案一角。原本要赶的归府时辰没有撤，只是这短短一段闲时，也终于不用藏在差事后头。"},{"id":"listen","label":"只听一曲，依礼送行","effects":{"mood":1},"bonds":{},"slight":null,"reply":"你示意他只管奏完，自己停在树影下听。\n\n笛音越过水面，到涂改处轻轻一顿，再慢慢收住。你没有替那半拍定好坏，也未叫他为了御前重奏一遍。\n\n允礼拂去袍角的花，见日影已移，便卷起谱页告辞。你颔首，他依时带着帖子出了园门。\n\n脚步远去，水面还有一点余声。今日听过一曲，往后的谈话仍留着开头；那页谱随他回府，没有被当成已经送出的礼或说定的下一次相约。"}]},"M10":{"id":"M10","title":"凯旋与军账","kind":"main","actor":"C03","location":"养心殿御案","body":"年羹尧的甲衣还带着赶路的尘，捷报却已整整齐齐呈到御案。\n\n他报完军情，终于抬眼。你看见他比离京前瘦了些，手背多一道伤；他却先问朝廷收到哪一封催粮信，说前营还有几处在等接济。\n\n殿外传着凯旋的喜讯。张廷玉将另一册放到捷报旁，指给你两笔相同的支领：日期一样，经手签押却未能一一对上。\n\n年羹尧看了许久，眉头拧起。\n\n“先查清，是该的。只是关外的人还在等粮。”\n\n张廷玉将原页留下：“要取转运原簿。只看这两行，还定不了是哪处出了错。”\n\n将军按住甲袖，既不愿拿战功免查，也不愿归来第一刻便只剩一册疑账。你记得自己从前怎样先猜忌、再试探，最后连一句平常问候也变得难以出口。\n\n眼前的捷报是捷报，待核的军需另有原凭。先问归人，仍可查账；先核账，也得给功与过各留一处。若封赏要缓，就须把缘由讲到他听得明白。\n\n年羹尧站直，等你在两册之间先开口。","options":[{"id":"welcome","label":"先欢迎归人，再共同核账","effects":{"stability":2},"bonds":{},"slight":null,"reply":"“一路辛苦。”你先问归程与将士伤病，才将军账翻给他看。\n\n年羹尧听完，把捷报推正，主动俯身看原页：“这一笔，臣认得经手的人，可以先取他的交接册。”\n\n张廷玉记下名字，没有将疑账并入捷报，也没有将疑点抹掉。年羹尧看见那两份纸分开放，绷紧的肩终于松些。\n\n迎归的话落到了人，核账仍落在实处。军需尚未拨定，前营还等下一道安排；至少今夜，他能把归途与难处一并说下去。"},{"id":"audit","label":"先核册，再议封赏","effects":{"execution":3,"mood":-1},"bonds":{},"slight":null,"reply":"你先点那两笔支领，请年羹尧说明原簿在哪里、由谁交接。\n\n他站直逐项答，凯旋的笑意淡了些，却没有拿捷报压住册子。说到一处未亲见的签领，他停下来：“这一项，臣须取原件再回。”\n\n你将那行留作待核，没有逼他当场认下。账翻到末页，才问归程，他静了一瞬，说一路尚好。\n\n今夜先把查账的口径问明，迎归的话来得晚些；未核的责任和未议的封赏各自留下，没有凭两行重复支领便判定谁负了朝廷。"},{"id":"delay","label":"暂缓封赏，清楚说明原因","effects":{"execution":2,"stability":-1},"bonds":{},"slight":null,"reply":"你将捷报单独收好，说明军需经手尚待核清，封赏先缓，不因此抹去已经呈报的功。\n\n年羹尧听到最后，拱手问：“要臣回哪几处？”\n\n张廷玉把原页推近，你们将待取的凭据逐项说清。他领下核查的差事，转身前又望过那封捷报。\n\n喜讯没有立刻换成赏赐，他心里仍有那一瞬的沉重；至少缓的是什么，今日说在了明处。账与粮还须另办，殿外那场庆贺也不能替你答完他方才的问题。"}]},"M11":{"id":"M11","title":"旧影新衣","kind":"main","actor":"C09","location":"养心殿暖阁","body":"甄嬛穿了一件新衣来，先问你颜色好不好。你尚未答，她便说起纯元。\n\n那名字落下，暖阁静了片刻。她没有笑着将话圆回去，只看着你，手指轻轻按住袖边。\n\n“皇上望着臣妾时，究竟在看谁？”\n\n她把这句话问得很慢，像已在心里排过许多遍，终于不肯再换成请安。案上有人备了赏单，正要递来，见她没有低头，便停在门边。\n\n你记得旧日有多少次，是一句好看、一份新赏，让真正的问题暂时消了声。眼前的人却已经听过太多旁人的解释，今日要的是你自己的回答。\n\n甄嬛松开袖边，又按回去：“衣裳可以改。臣妾不想一直猜，自己哪一句、哪一处，才算被皇上看见。”\n\n你未必已想好往后怎样与她相处，却知道自己为何迟迟没有开口。承认旧影不该压在她身上，或说明今日真实的心意，都比点一份赏单难得多。她仍在等，并不想再替你的沉默找缘由。\n\n门边的赏单还没有展开。她等你开口，没有替这阵沉默说一句臣妾明白。","options":[{"id":"clear","label":"明确不作旧人比较","effects":{"palace":2},"bonds":{},"slight":null,"reply":"你没有再借颜色转开话题：“你是你，不该拿旁人的样子来比。”\n\n甄嬛听完，眼眶微红，却没有低头谢恩，接着问你从前那些话，又有多少是看着她说的。\n\n你让赏单先放下，听她把问题讲完。她也没有因一句澄清便将旧疑一笔抹去，只把一直压在袖下的手松开。\n\n今日你答了最要紧的一句，余下的信任仍须往后相处。她离开前重新看过自己的衣袖，没有再问颜色像不像谁。"},{"id":"polite","label":"维持礼遇，清楚说明疏离","effects":{"stability":1,"mood":1},"bonds":{},"slight":null,"reply":"你说明往后仍会依礼相待，也把私下的疏离说清，没有再拿赏赐填那一点沉默。\n\n甄嬛听了很久，才问原先的话是否还该照从前理解。你没有让她继续猜，她便慢慢点头：“臣妾听明白了。”\n\n她起身整理衣袖，谢的是今日说清，神情仍有难过。门边的人收起尚未展开的赏单，暖阁里也不再添一句来日再说。\n\n她出门走得慢，却没有回头再求一个含混的答复。礼遇照旧，这一刻的距离被两个人听见。"},{"id":"vague","label":"含混赏赐，避开回答","effects":{"treasury":-2,"mood":-2},"bonds":{},"slight":null,"reply":"你夸过新衣，又吩咐添赏，将她问的那句放到一旁。\n\n甄嬛脸上的笑迟了一瞬，仍依礼谢恩。门边的人展开赏单，两点用度从账上划去，她却没再问其中有什么。\n\n你让她坐，她坐了片刻，杯中的茶一直未动。告退时，她把衣袖理得比来时更平整，像方才只谈过颜色。\n\n门合上后，那句没答的问题仍留在暖阁。赏已记实，你也暂时避过了难堪；她没有亲口说疑虑已消，往后不能把这一场谢恩当成全都讲明白。"},{"id":"open","label":"“朕想了解的，是你自己。”","effects":{"palace":2},"bonds":{},"slight":null,"reply":"你将赏单放下，先看清眼前的人：“你不是旁人的影子。朕愿意了解的是你，往后的话，也该听你自己的。”\n\n甄嬛抬起眼，却没有立刻笑：“那臣妾若有不像她的地方呢？”\n\n“便听你说。”\n\n她慢慢讲起今日为何选这件衣裳，话到一半，又问你是否真的愿听不顺心的回答。你没有催她就此安心，也没有伸手留她。那盏茶终于被端起，喝过一口，又放回原处。\n\n“臣妾还须想一想。”她说。你将这句话认真听完。今日说清了愿意了解，尚不是彼此已经相爱。"},{"id":"unsure","label":"“朕还没想定，不该请你等。”","effects":{"palace":2},"bonds":{},"slight":null,"reply":"你没有指向赏单：“你不该被拿来与旧人比较。至于朕自己的心意，眼下还没想清，不能拿来日二字请你等着。”\n\n甄嬛低头看过衣袖，过了一会儿才问：“那臣妾不等，也不会因此被怠慢？”\n\n“礼遇照旧。你也有自己的意思。”\n\n她轻轻点头，把那只一直攥着的袖角理平。这一次没有笑着谢恩，也没有被要求留下一个将来必会回心的答复。\n\n出门前，她说衣裳是自己喜欢的颜色。你没有接一句像谁。未定仍是未定，今日却少了一场靠猜测维持的亲近。"}]},"M12":{"id":"M12","title":"六宫新规","kind":"main","actor":"C06","location":"景仁宫","body":"宜修把两年的宫账摆上案，最旧的一册已经磨了角。\n\n“这处交接改过了，这处还在等。”她翻给你看，停在几张夹着纸签的页上。有的是份例，有的是协理签核，同一桩事换个经手人，便又要重新请示。\n\n窗边添了新炭。宜修将笔放到你手边，自己仍留着一张空纸，准备记你今日究竟准哪一条。\n\n“若只靠臣妾次次在场，等臣妾病一日、歇一日，他们又问谁？”\n\n她说完，用指尖压住一页，免得待议的纸签被合进去。她想把宫中琐事真正交接下去，也清楚按家世另排协理能少得罪哪几家；只是那样一来，重叠的签押又要绕回旧人情里。\n\n你看着那些批过、又重新呈来的字。相赠的玉和几句温言，都不能替这一页确定往后谁可以作主。\n\n“今日写下去，臣妾便按这个呈。”她抬起眼，“若还要等，也请让这几页继续露着。”\n\n宜修又看一眼那张空纸，手边的茶已经放凉。你想让她少熬一夜，却也看见那几页为何总要跟着她回来。墨已经磨好，她没有先替你写下一个好字。","options":[{"id":"system","label":"写明份例与协理权限","effects":{"treasury":-2,"palace":5,"execution":2},"bonds":{},"slight":null,"reply":"你们把份例与协理签核逐项写清，拨出两点供誊录核发。\n\n宜修逐行复述准到哪一处，再将正副两份分开。遇到原来重叠的名目，她停笔问清，不因已经落了朱批就匆匆带过。\n\n最后一页压好，她才长长松一口气：“再换人接手，也先拿这一份看。”\n\n今夜写成了可照办的规矩，各处是否真正照做，仍要看后来交接。她把笔收进匣里，案上终于空出一小块地方，够放一只不压着账页的茶杯。"},{"id":"comfort","label":"先安抚，制度暂缓","effects":{"mood":2,"palace":-2},"bonds":{},"slight":null,"reply":"你先问她这些日子累不累，让她缓一缓，条文暂不落定。\n\n宜修谢过，端起温茶喝了一口。你等她放下杯，才看见她的另一只手仍按在那几张纸签上。\n\n“那这些，臣妾再留着。”\n\n她没有争，将待议页另夹好，合账时仍露出一角。今夜的体谅落到了人，原来不清的份例与权限却没有跟着清楚。你问她是否还要带走，她点头：“下回还得看这一册，免得又从头问。”"},{"id":"family","label":"按家世分配协理","effects":{"stability":2,"palace":-3},"bonds":{},"slight":null,"reply":"你按家世重排协理，先将几处分派写定。\n\n宜修逐项记下，没有略过原先圈住的牵连。抄到第三处，她将两个人名用一条细线相接：“这一件，仍要两处都点头么？”\n\n你低头核看，她便取来新纸，把经手与请示的次序重新列起。门第之间有了新的照顾，那些事落到谁手里反倒添了转折。\n\n今夜不是没有决定，只是决定了便得照实记下代价。宜修将旧签留在新页旁，灯还要再亮一阵，没人把这本账写成已全理顺。"}]},"R02-01":{"id":"R02-01","title":"留茶","kind":"relation","actor":"C02","location":"养心殿暖阁","body":"茶盘已移到案角，苏培盛却仍站在灯影边上。你让他不必忙，他反倒低头理了理本就平整的袖口。\n\n“皇上可还有吩咐？”\n\n你摇头。他便不知该把手放在哪里。只要有差事，他总能妥帖接住；没有折子要递、没有人要传，空出的一点安静却像另一道难题。\n\n炭盆旁有个暖些的位置。你问他那里是不是不冷，他顺着目光看过去，半晌才回：“暖和。”\n\n两个字里少了一个奴才。他自己察觉了，抬眼等一句责备。你没有责备，他却也没敢将这份宽待立刻当成别的意思。\n\n“值房那只手炉，又不知叫谁拿去了。”他说完便想收住，像这种话不值得占御前的时间。\n\n你将折子合起，等他往下说。他望过案上的两只杯，又问明日更次是否还要核。闲话与正事，他都愿接，只是想先听清你留他的缘由。\n\n门外有人轻声换班。苏培盛没有跟着退出去，拂尘却仍握在手里，等你给这片刻一个他听得懂的开头。","options":[{"id":"warm","label":"“没有差事，陪朕说会儿闲话。”","effects":{},"bonds":{},"slight":null,"reply":"“没有差事，陪朕说会儿闲话。”\n\n你先合起册子，把两只杯的位置留出来。他望一眼门口，见无人催，才将拂尘搁下。\n\n“手炉昨日又叫小夏拿错了。”他讲到磕掉的铜角，自己也笑了。你问后来找着没有，他竟肯说还没有，没急着替一句小事收场。\n\n茶慢慢温下来。他留下的这一会儿，终于不必全拿差事来证明用处；什么时候告退，仍可以亲口说。"},{"id":"work","label":"“明日的更次，你我一起看看。”","effects":{},"bonds":{},"slight":null,"reply":"你将名册摊开，请他从最难衔接的那一处说。\n\n苏培盛熟悉的神色回来了，却没再独自抱走整本册子。他指出两处顺序，等你问完才往下翻，连原先怕被怪罪的疏漏也讲明。\n\n“不是再添奴才一更就能接上的。”这句终于没被他咽回去。\n\n你们将待核之处夹好。册子尚须后续经办，他今夜先有了能一起看难处的人，没有借共事许下别的意思。"},{"id":"distance","label":"“照旧便好，不必另猜朕的意思。”","effects":{},"bonds":{},"slight":null,"reply":"你把来意说明：照旧按御前规矩往来，不必因为多问一句就另猜私下意思。\n\n苏培盛轻轻点头，那一点无措渐渐落定：“奴才明白。”他把拂尘搭好，仍认真提醒炭盆离案角太近。\n\n你将它移开半寸，他才放心，照常报完值守，没有因分寸说清便少答一件事。\n\n帘子放下时，外头仍留着灯。职责与照料没有被收回，他也不必把每一句体贴都当成新的考问。"}]},"R02-02":{"id":"R02-02","title":"初次请坐","kind":"relation","actor":"C02","location":"养心殿暖阁","body":"苏培盛回过明日的几件事，站得久了，不动声色地换一换重心。你将案侧的空椅转过半寸，他立刻望向门口。\n\n“奴才站着回话也是一样的。”\n\n小太监刚退下，暖阁只余你们两个。他像怕少了旁人提醒，自己便失了分寸，反将背挺得更直。\n\n你没把椅子再推过去，只问腿是不是疼。\n\n“旧毛病，天冷就有些。”他答完又低头，“不碍事。”\n\n椅背搭着一块软垫。你记得它一直放在里间，从前没人想到搬来案边。苏培盛看见那垫子，手已伸出去，像要先替你铺好，伸到一半才停住。\n\n“皇上是要听名册，还是……”他没把余下半句说完。熟悉的差事他不会躲，另一种体贴却让他一时不知该怎样领受。\n\n你把册子留在案上，也把手收回来。坐下、站着，或只把回话讲完，都还来得及由他自己选。门边的风掀起帘角，他低头按住膝头，终于不再抢着说没有疼过。","options":[{"id":"warm","label":"“坐着说，朕想听你说完。”","effects":{},"bonds":{},"slight":null,"reply":"“朕想听你说完。坐着站着，你自己选。”\n\n你先低头看册，给他一点不必被注视的余地。衣料轻擦椅沿，过了一会儿，案侧终于多一个坐着的人。\n\n苏培盛报完最后一件事，没急着起身：“手炉找着了，原就在奴才自己柜里。”\n\n你抬眼，他先笑了。那句不打紧的话是他自己留下的，椅子也不是又一道必须领受的命令。暖阁安静下来，这回他愿坐稳了再说。"},{"id":"work","label":"把名册递过去，请他坐着回话","effects":{},"bonds":{},"slight":null,"reply":"你把软垫留在椅边，将待问的名册递过去，请他按舒服的姿势回话。\n\n他终于坐在椅沿，从一条难接的更次说起，主动补上一处原来没人问过的难处。你在页边记，他便等你写完，不再赶着自己扛下整页。\n\n“这样回，倒不怕漏了。”\n\n册子合上，两个人核到同一行。他扶膝起身，神情踏实；坐或站没有成为恩许的暗语，今晚确实把一段共事的话讲完整了。"},{"id":"distance","label":"不再劝坐，问清腿疼与更次","effects":{},"bonds":{},"slight":null,"reply":"你收回劝坐的手，说明按他习惯便好，腿疼照实报，值守仍按册办。\n\n苏培盛答得平稳，将垫子收在近处，站着把剩下的话回完。你没有再借体谅催他靠近，他也不必找一个让你满意的坐法。\n\n临走，他指出窗边漏风的缝，说会交人补上。那份周全仍认真，未因你说明分寸便撤去。\n\n椅子空着，没有人因此受责；今夜留下的是一段双方都听明白的相处。"}]},"R07-01":{"id":"R07-01","title":"停香解释","kind":"relation","actor":"C07","location":"翊坤宫","body":"年世兰将香盒往桌上一放，盒盖碰得清脆。\n\n“今日换过什么，臣妾都记下了。”她望着你，“只是这几行记得再清，也不会自己告诉臣妾，为什么。”\n\n颂芝要来添茶，被她挥退。旧香停了，屋里只余炭火原本的气味；她的手按在盒上，连那一下轻颤也不肯用袖子遮。\n\n“若是怕臣妾烦，皇上不妨直说。别只留下一个安排，叫旁人都比臣妾知道得多。”\n\n你看见她已把近来的睡眠和不适写在纸角，又将纸翻过去。她愿问医，也愿自己记，只不愿每回追问都像不识抬举。\n\n窗边一只花盆被她转过向阳的一面。做完这个小动作，她才回来坐定，仍等你亲口说明哪些已知、哪些未知。暖香没了，原来的喜怒却没有跟着被收进盒子。\n\n她没有先要一句永远照顾的话，只把那页记过字的纸重新摊开：“臣妾自己的身子，总该听见实话。今日说得不好听，皇上也得容臣妾问完。”","options":[{"id":"warm","label":"把疑虑、留样和未查清的事都告诉她","effects":{},"bonds":{},"slight":null,"reply":"你耐心听她问过原方与起居，能答的照实答，未知的也明白留着，没有拿猜测代作检验结果。\n\n年世兰起初冷着脸，听到最后问：“若臣妾今日不问呢？”\n\n“也该来告诉你。”\n\n她转过脸，许久才将香盒移开，重新摊起自己记过的那页：“那下回问医，臣妾自己也问。皇上别嫌问得多。”\n\n她端起一直未动的茶。旧疑不因一席话全散，却终于能从自己要知道的地方问下去，今夜不必只等旁人来安排。"},{"id":"work","label":"请她亲自留一份起居记录","effects":{},"bonds":{},"slight":null,"reply":"你请她亲自留起居记录，说明能问医、能核来源的口径，也让她保留自己那一份。\n\n年世兰听见自己留着，立刻叫颂芝取纸，把近来的几处不适写清，没再用一句没什么遮过去。\n\n写到末尾，她推到你面前：“这些，也劳皇上看仔细。”\n\n你接住，未把她的追问当使性子。今晚先留下能共同查的记录，检验尚无结果；她不必靠私下亲近，才得到一份关于自己身体的实话和凭据。"},{"id":"distance","label":"说清照护安排，也说清今后的来往","effects":{},"bonds":{},"slight":null,"reply":"你将眼前照护与待核的安排说清，也说明宫务之外仍按礼来往，不拿含混的体贴留她继续猜。\n\n年世兰脸白了一瞬，随即抬起下巴：“臣妾听明白了。身子的事，自会追问。”\n\n她没有留茶，仍叫颂芝把自己的起居记录备给医官。该有的照护没有撤，你也没把她的难过当作不识抬举。\n\n门外风吹进来，香盒合着，她重新看那页字。私下来往说到这里，问清身体与来源的权利仍好好留在她手里。"}]},"R07-02":{"id":"R07-02","title":"公开尊重","kind":"relation","actor":"C07","location":"翊坤宫","body":"颂芝送来新香单，年世兰看也没看，先问是谁挑的。听说按内务府旧例，她笑了一声，将单子平平放下。\n\n“本宫屋里用什么，最后一个知道的，倒是本宫。”\n\n你进门时，她没有像往日那样迎上来。经手的人夹在中间，等一句照旧办，便能把这张单子再收回去。\n\n年世兰却将纸按住：“来源、用料，一样一样说。问两句，总不算又使性子吧？”\n\n那人先望你，没有立刻回她。她看见了，也没有把话改得软些。上回私下能问清的事，到了旁人面前，究竟还是不是她能过问的事，今日就落在这一眼里。\n\n窗边的花开得亮，是她自己选的。她伸手摘去一片枯叶，回头又看香单，像在等你是否真将那两样都当作她的生活。\n\n“皇上觉得，这样也算妥帖么？”她问。经手的人捧着副单，笔还未动，你的回答会让他知道接下来该看向谁。","options":[{"id":"warm","label":"当着众人的面，让她自己挑","effects":{},"bonds":{},"slight":null,"reply":"“不算妥帖。”你当着颂芝与经手人的面答，“她屋里的东西，先拿给她看。”\n\n年世兰预备好的硬话停了一瞬，随即取笔划去两味，又将自己想问的一行添上。经手的人这回等她核完，才收副单。\n\n人退下，她指窗边的花：“这个也是臣妾挑的，皇上方才看见了？”\n\n你说看见，她终于笑：“那坐近些，站在门口哪里看得真。”香单与那盆花，都不必再被当成她闹脾气的理由，今夜她肯留你看自己喜欢的东西。"},{"id":"work","label":"让经手人逐项回她的话","effects":{},"bonds":{},"slight":null,"reply":"你让经手人将用料、来源与待核处附在单后，逐项回年世兰的话。\n\n那人起初仍看你，听你请他看着她答，才转过身。她问过几处，比你想得更细，遇到没答清的便留下，不忙着签成样样妥当。\n\n“这回知道用了什么，也知道问谁了。”\n\n签过的副单仍留一份在宫里。合作有了能追问的凭据，未把尚待核验的身体结果编出来。窗下的花被她转向光亮处，那是她自己作的决定。"},{"id":"distance","label":"依宫务议完，尊重她的决定","effects":{},"bonds":{},"slight":null,"reply":"你依宫务说清由她先阅、你核经手责任，不将这件事另解释成私下邀她亲近。\n\n年世兰点头，将不喜欢的两味划去，逐项问完再交颂芝。经手的人不再越过她，只等御前一个眼色便走。\n\n议完她没有留你，亲自将副单收好，又吩咐那盆花别挪。你听见，也依礼告辞。\n\n今晚照样把能作主的交回她手里；距离不等于用度或身体照护降一等，她也不必用留茶来换这份应有的尊重。"}]},"R06-01":{"id":"R06-01","title":"玉环","kind":"relation","actor":"C06","location":"景仁宫","body":"景仁宫只留了两个人伺候。宜修将玉环搁在帕上，先问茶要浓些还是淡些。你答过，她却没有立即唤人，指尖顺着玉的内沿慢慢抚过。\n\n“皇上还记得这是哪年挑的么？”\n\n你说出年岁，她眼睫动了一下。那时说几句家中琐事，不必先找一个能呈御前的名目。如今她等过片刻，才自己将玉戴好，低头看看，并没有拿这动作向你索一句话。\n\n“臣妾有一件不讨喜的事。”\n\n她讲到一位老嬷嬷想归养，先将所需与待核的说清。讲到路上怕冷，话忽然停住，仿佛这种小事又不该挤在正事里。\n\n殿外有人收灯。她把名册留在案侧，没先催你批，也没将旧年的心事借玉环都倒出来。她想知道你愿意听到哪里，自己才好决定说到哪里。\n\n“若皇上今日只想看账，臣妾也备好了。”她将手从袖里移出来，两份纸都摆得平整，却不替你选哪一份先打开。","options":[{"id":"warm","label":"“你说，朕听着。”","effects":{},"bonds":{},"slight":null,"reply":"“讨不讨喜，听完再说。”\n\n宜修讲起老嬷嬷归养，起初措辞周全，渐渐连怕路上受寒的小事都说了。你没有打断，也没让她先将琐事删成一份好批的折。\n\n讲完，她轻轻一笑：“这些原不必拿来烦皇上。”\n\n你替她续茶，答方才问愿不愿听，朕已经答过。戴玉环的手终于不再往袖里藏。\n\n事情尚有待核，今晚却先有一个人肯听她把自己的在意说完整。她没有用那只玉环索更多，你也没催她立刻放下旧疑。"},{"id":"work","label":"请她说说这件宫务准备怎样办","effects":{},"bonds":{},"slight":null,"reply":"你请她摊开归养名册，先讲准备怎样办。宜修将所需和未核之处分别标出，没有将那件事借旧情直接讨成恩准。\n\n你逐项问，她逐项答，到末尾才落一句按核清的再呈。正副两份收好，待办仍有自己的次序。\n\n“下回臣妾就照这一页回。”她说。\n\n玉环轻碰案沿，声音清亮。今晚先把一件宫务讲到能继续办的地方，既未许定亲近，也没有因只谈共事便敷衍她的判断。"},{"id":"distance","label":"先说明宫务之外的来往","effects":{},"bonds":{},"slight":null,"reply":"你先说明往后以宫务相商，私下不再另许她意。宜修静一会儿，自己将玉环放回匣中，取出归养名册。\n\n她讲得清楚，你听得仔细，所需与待核仍按同样的口径看，没有因距离说清就收走她应有的权责。\n\n“皇上既说明白，臣妾便不必再猜。”\n\n她依礼送到门边。今晚的难过没有被劝成欢喜，能办的事也没被丢下。匣子合好，案上仍留着那页可以接着呈的册。"}]},"R06-02":{"id":"R06-02","title":"共理宫账","kind":"relation","actor":"C06","location":"景仁宫","body":"宫账铺开，宜修先递一张空白纸：“看不清的名目，写在这里。免得翻到后头，又忘了前头问什么。”\n\n她自己那张已有十来处批注。账翻到一半，烛芯结花，她伸手取铜剪，你正好将它递过来。灯亮了，她道一声谢，又低头指向重叠的两个名字。\n\n一件事在两处都能领差，到最后签核却都说该问另一处。她查了几日，不缺一句相信皇后，缺的是能把经手问到底的口径。\n\n“臣妾想查清，也想查完以后，不再隔月重来。”\n\n你问她已想过什么改法。她的笔尖在纸上停了一瞬，像不惯有人先问判断，再看账对不对。窗外更声过去，她没有拿疲惫催你留下，也没先将一处含混的数抹成圆满。\n\n两张纸并排，空的一张仍等你落笔。眼前可以共同看完，也可以按职责逐项核清；宫务之外要不要多说，仍是另一层能说清的意思。宜修把待问那页翻回最上头，没有再让它躲进账尾。","options":[{"id":"warm","label":"照她的思路，一起把这本账看完","effects":{},"bonds":{},"slight":null,"reply":"你把空纸放到她那张旁，照她的顺序问：“这一处，你已经想过怎样改？”\n\n宜修点头，说到第三条时语速快了一些。你听完才落笔，她也不必先替每句话铺好退路。\n\n账合上，茶已凉了。她看见你写歪的一行，忍不住笑：“皇上批折的字，原来也有认不出的。”\n\n你将纸翻过一点，她提笔补最后两个字。待核仍留着，今晚先留下这份可以不同意、也可以笑出来的自在，不用整本账全无差错才配多坐片刻。"},{"id":"work","label":"核清权限，请她依方案复核","effects":{},"bonds":{},"slight":null,"reply":"你在重叠名目旁留下批注，请她按列出的口径复核。宜修先问清哪处归谁签，再把待核的纸夹进册中。\n\n“这样，底下回话便有得对。”\n\n她请你再核一次余数，你们算到相同的一行才放下笔。今晚核清的就是这一页，未将满宫的旧账都说成从此无忧。\n\n窗外换更，她将正副两份收好。宫务上的默契有了实际落笔，私下的关系仍照双方所说，不拿一场共事代替另一种答应。"},{"id":"distance","label":"只谈账目，把批注留下","effects":{},"bonds":{},"slight":null,"reply":"你们按账目逐项核过，宫务之外没有另谈。宜修折起签核重叠处，请留下明确批注，你照实写，她再核一遍。\n\n两份分开，她答会按这个呈，不必借留坐或旧情才让这句有分量。\n\n临走，她照礼让人奉热茶，你暖过手便起身，没有将那份周到再读成未说出的邀请。\n\n旧账没有少一项该核的，彼此也不用多猜一层。今夜的合作完整做完，原来说明的距离同样被认真留住。"}]},"R08-01":{"id":"R08-01","title":"宫宴维护","kind":"relation","actor":"C08","location":"养心殿暖阁","body":"安陵容在廊下停住，把方才唱完的末句又轻轻哼了一遍。听见你的脚步，她收声行礼，手指仍捏着帕角。\n\n你问后半句为什么转调，她怔怔抬头，像没想到宫宴散了，曲子里的一处细节还会被记得。\n\n“原谱高些。臣妾今日气息不够，临时转了。”\n\n你问改得不好么。她想了一会儿，没有先说自己浅薄，小声讲起那几个字的咬音。她确实不满意一处，却也知道有一处比从前更稳。\n\n“若只说唱得好，臣妾倒不知该改哪里。”她说完，自己也有些意外，仿佛这句话不该是她主动提的。\n\n廊边有人收乐器，她看了一眼，担心御前不过随口夸过，明日留下的又只是一次受人照拂的难堪。她想再试那一段，也想让改处是凭耳力留下的，不只因你肯留步。\n\n你没有取赏单，等她把那处转音比给你听。安陵容慢慢松开帕角，声音终于能从自己觉得不顺的地方继续。","options":[{"id":"warm","label":"“再唱一遍你改过的，朕想听。”","effects":{},"bonds":{},"slight":null,"reply":"“朕想再听一遍，你改过的这一段。”\n\n安陵容清了清嗓，起调仍轻，末句却稳住了。你指出自己听得最好的一处，也等她讲仍想改的那一下，没有只夸人乖巧。\n\n“原来皇上听见了。”她攥帕的手渐渐松开。\n\n你问愿不愿把两种唱法留下，她答愿意，还想再试一处。话说得比方才快，里头终于有她自己的主意。今夜被听见的不只是受过委屈的人，也有一段她真想唱好的曲。"},{"id":"work","label":"请她署名留下这段改谱","effects":{},"bonds":{},"slight":null,"reply":"你请她署名留下原谱与改谱，先标出转调的那一处，供掌乐比较。\n\n安陵容听见具体段落，才明白不是随口赏一句。她说今夜能先抄这一行，余下仍要核，不为了讨好便答明日全齐。\n\n“名字也写上么？”\n\n你点头。她将纸页拿稳，脸上有一点克制不住的认真。今晚先有可继续做的第一步，尚未将未抄完的谱说成全交到人手；那一段改法，却已经不必再匿名藏在别人的曲子里。"},{"id":"distance","label":"依礼鼓励练曲，说明相处分寸","effects":{},"bonds":{},"slight":null,"reply":"你依礼鼓励她练曲，也将今后相处的分寸说清，不让一句认真听过变成含混的私下许诺。\n\n安陵容低头片刻，应了一声。你没有追问家中或心事，她便试着说哪一个转音还不顺，声音虽轻，却没有再全盘否定自己的改法。\n\n你告辞，她重新起调。这回到末句，没有因谁走近便停。\n\n今晚没有被选作另一种亲近，曲子仍能凭本领被听。她该有的练习与礼遇都留着，不须为一句距离交回自己的声音。"}]},"R08-02":{"id":"R08-02","title":"私下倾听","kind":"relation","actor":"C08","location":"养心殿暖阁","body":"安陵容把家书折过两遍，又重新展开。桌上压着自己抄的曲谱，墨尚未干，她先将信挪开，怕沾上字。\n\n“信里说家中一切都好。”她顿了顿，“末尾又添了几行。”\n\n她没有递信，只说那几行里的请求。讲到一半先替家中辩解，辩解完又停住，像怕你听见她开口，便只等下一句要什么。\n\n窗外有人试弦，一根弦松了，响得不准。她听一耳朵，下意识说该往紧处调，才想起家书尚未讲完，脸上有些赧然。\n\n“臣妾不想每次说起自己，都只剩家里又求了什么。”\n\n你没催她将信给你。她也没有趁沉默把请求再复述一遍，手移到曲谱旁，想说一处练了几日还不稳的高音。\n\n家中来信确实让她为难，却不是她今日仅有的话。案上那张墨未干的纸，也有她想学、想做和想改的地方。她将两样分开放，等你听的是其中哪一件，不再先把自己的话缩成一句都听皇上的。","options":[{"id":"warm","label":"“先说你自己，朕还想听。”","effects":{},"bonds":{},"slight":null,"reply":"你没拿赏赐截住她的话，也没要她把家书递过来。\n\n“先说你。曲谱改到哪里了？”\n\n安陵容看看未干的墨，将信放在一旁，讲总唱不稳的高音，又讲小时候躲在门后学曲。你听她说到自己想再试什么，才接着问。\n\n临走，她把新改的一行推过来：“这一处，想请皇上下回再听。”说完有些赧然，却没收回。\n\n那是她表达的期待，尚未定日；今夜先留下一个能说自己喜欢什么的人，不只剩替家中请求的声音。"},{"id":"work","label":"问她想学什么、愿做什么","effects":{},"bonds":{},"slight":null,"reply":"你问她想学什么、愿意先做哪一件。安陵容想过，答愿将掌乐处旧谱的疑处先列清。\n\n“臣妾听得出有几处传抄不同，只是不知有没有人肯听。”\n\n你请她按听到的写，不必先说全部改得对。她翻到纸背，一笔一笔列，到了第五项，已不再先赔一句无能。\n\n家书暂搁远处，教学与差事还须再议，没有凭这一次相谈直接授什么新职。今晚确实留下的，是她自己选的一步和能接着核的那张纸。"},{"id":"distance","label":"让她自己回信，只商议眼前事务","effects":{},"bonds":{},"slight":null,"reply":"你说明家书可由她按自己的意思回，不必将私人请求都呈给御前；宫中事务仍能按所长商量。\n\n安陵容沉默片刻，将信叠好收回袖中：“臣妾知道该怎么回了。”\n\n她没有再拿家里请求等你代答，转而问整理曲谱的第一步。你们议清疑处怎样列，她送到门边便回去取笔。\n\n今晚的界线没有替她决定家书，也没有夺走能凭本领做事的余地。你离开时，纸仍由她自己摊着，后半句话也终于能自己写。"}]},"R04-01":{"id":"R04-01","title":"雨廊","kind":"relation","actor":"C04","location":"养心殿暖阁","body":"廊檐将雨水接成一线。温实初把药箱移到灯下，先擦净箱角，才将护在里面的两页脉案抽出来。\n\n“箱里这几张纸，比别的还怕湿？”你问。\n\n他打开一角给你看。纸边已软，一处小字却反复添过批注；那一行不在御前要问的几项里，他原想讲，手又按回箱扣。\n\n“有个病人，换了几位医官，叙述总被抄得很短。”他停了一下，“臣想把那一句留全。”\n\n你没催他跳到结论。他才讲起同一段不适在不同日子怎样说，哪些是确实听见的，哪些还得回去再问。说到熟悉处，拘谨淡下来，箱扣也终于放开。\n\n雨一时停不了。值门的人候着，温实初瞥见漏刻，又想将纸收起。他怕御前不过顺口一问，自己却把求知的心事讲得太满；也怕一句赞许，将未确诊的医事写成了功劳。\n\n你将另一盏灯挪近。他看清那行小字，轻轻道谢，仍没有替病人删去那个尚待回答的问号。","options":[{"id":"warm","label":"问起那两页脉案背后的旧事","effects":{},"bonds":{},"slight":null,"reply":"你问他为何将那两页留得如此仔细。温实初便讲初次随师父出诊，漏过病人一句闲话，后来才知道那句不能删。\n\n“如今再抄，便想多问一句。”\n\n你没有急着夸医术，只接住他说过的细处。他望你一眼，将脉案合好，又主动讲起学医时怎样记错一个字。\n\n雨还没停，两人却都笑了一下。医事之外那段旧事，是他自己愿意添上的；你没有因听过它，就替他把其余心事都取走。"},{"id":"work","label":"请他讲清脉案中的变化","effects":{},"bonds":{},"slight":null,"reply":"你请他把前后变化逐项讲清，哪些能由脉案确认，哪些还要复诊。\n\n温实初将纸铺平，一处处指给你看。你复述时误过一个次序，他便指正，没有为了顺耳而认下。\n\n“病人说过的话，不能只挑合心意的听。”\n\n你照他的意思改回。临行，他将两页分开夹好，留下待问的记号。这回没有私人追问，仍有一份判断被尊重的踏实；尚未查明的病情，也没有被御前一句赞许催成结论。"},{"id":"distance","label":"只问医事，让人备好避雨衣物","effects":{},"bonds":{},"slight":null,"reply":"你只问医事，说明私下的旧事不必因御前问起就全说。温实初依脉案仔细答，手不再压着那页纸。\n\n议完，你请人备好避雨衣物。他谢过，又照医官职责提醒今夜少熬些时候，语气与方才同样认真。\n\n没有人拿照护换一段亲近，他也不必因说清分寸便将医者的叮嘱收回。\n\n药箱扣稳，他从干处走回廊边。留下的原页仍有待问之处，这一次，医事和私事都没有被含混带过去。"}]},"R04-02":{"id":"R04-02","title":"倾听志愿","kind":"relation","actor":"C04","location":"养心殿暖阁","body":"太医院新抄的脉案送来，几页字迹与你上回见的不同。温实初指着一处字，竟笑了笑：“新来的医官，总在这里漏一笔。”\n\n你问教人是不是很费工夫。\n\n“费。”他答得坦白，“可总得有人接着做。”\n\n他讲起想整理的几类病案，话到一半，听见门外又报御前当值，便把一页纸折回去。你问那页是什么，他说只是自己列过的教学次序，还没核完值诊。\n\n纸上先写谁能讲哪一段，后面留着复诊的空栏。他没有为了显得办得成，先将病人的时辰划去；真能留给教人的时间，比愿望少得多。\n\n“若来回传召，倒容易叫等诊的人扑空。”他将这句说完，等你反应，没有马上添一句全听安排。\n\n你把折回的纸摊平，问他想从哪一页教起。温实初终于不再急着收走，指尖停在最前面的旧案上。那一页既是职责，也是他自己的念头；是否愿意多听一点，你仍有余地回答。","options":[{"id":"warm","label":"“把你想做的，说给朕听。”","effects":{},"bonds":{},"slight":null,"reply":"“把你想做的说给朕听，先不急着替值诊答应。”\n\n温实初将折回的那页取出，讲谁能教哪一类案，哪些尚须自己再问。他说到喜欢处，眼神比方才亮些。\n\n你没有替太医院当天排完班，只让他核妥当值后再呈。他收纸时却不再急着藏：“若这页写得清，下回想带来给皇上看。”\n\n那是他自己盼着的下一回，尚不是说定的约期。你听见一个医官也有留给自己的心愿，肯让它慢慢说完。"},{"id":"work","label":"一起核清问诊和教人的时间","effects":{},"bonds":{},"slight":null,"reply":"你们将当值、复诊与教学分列。温实初先圈冲突的两处，没有为了显得办得成，把病人的时辰划去。\n\n你问哪些必须等回报，他便留下空栏，说明由谁再核。一页想法因而有了可继续讨论的次序，却还没变成已经排定的官署日程。\n\n他将纸收好：“这样呈，才知道缺的到底是什么。”\n\n你们没有另谈亲近，仍将一件他在意的事推进到更清楚的一步。门外再来通传，他这回能带着自己的判断出去。"},{"id":"distance","label":"按医事议安排，也收下他的叮嘱","effects":{},"bonds":{},"slight":null,"reply":"你说明仍按医职商议，不借先前的相处向他多索心事。温实初点头，将教学所需和当值冲突一一列清。\n\n未定的两处仍待核，你没有让他以一句全听圣意代答。他也照常把作息建议放到案边，指向那行“亥时前歇”。\n\n你看着笑，他笑回一句：“这一条，臣下回还是要问的。”\n\n医者的认真没有因距离收回，教学也不靠私情获准。纸页分好，他按当值告退，话说得清楚，双方都不用另猜。"}]},"R05-01":{"id":"R05-01","title":"御园听笛","kind":"relation","actor":"C05","location":"御花园","body":"允礼将旧谱放在石案上，敲了两下。你跟着敲，慢了半拍，他没忍住笑：“皇兄看折子时，也这样抢着往下么？”\n\n话出口，他将手收回一点。你示意不用找补，他便把笛横在膝上，重新打起节拍。这回你等他敲完才接，两下声音终于落在一处。\n\n王府的帖子压在案角。远处随从往前半步，他先点头，再告诉你今日回府尚有一件待答的差事。\n\n“这段今日说得完。余下若还想听，得另择一日。”\n\n他没有把日程说成推辞，也没因此急着将谱收走。风掀起一角，你看见纸背还有修琴的几笔小记，不是宗室差事的名目，倒像他原本留给自己过的一个下午。\n\n你望向那行字，他也望见了，笑问是否连这个都要回御前。说笑里有一点试探：皇帝想听的是一位王爷随问随答，还是这个人自己选的琴与谱。\n\n他将帖子与谱页分别压稳，既没催你亲近，也没有把宫门外的日子都藏起来。","options":[{"id":"warm","label":"问问他宫门之外的那个下午","effects":{},"bonds":{},"slight":null,"reply":"你问宫门之外那个下午，他原想怎样过。允礼有些意外，随后讲起府里修坏的一架琴，和坚持木料没错的老匠人。\n\n你听着笑，他也笑，翻到谱上夹纸签的一处：“真想学，下回从这里来，别又抢拍。”\n\n你在纸签添一小点墨，认下方才的节拍，没有因此写定下一次入宫。\n\n随从来提醒，他便收起帖子。临行扬一扬笛子，话里少了客套，却仍保有自己回去的下午；这段闲话是他愿意留下的。"},{"id":"work","label":"先听王府近来的差事","effects":{},"bonds":{},"slight":null,"reply":"你先听王府近来的差事，允礼将两处来往说明，又从帖子里抽出待答的原文。\n\n你问到细处，他说清哪项已知、哪项须回府再核，没有因御前在问便立刻答圆满。议清后，谱与帖子分别收好，各归原处。\n\n走到园门，他忽然补一句：“方才那半拍，皇兄倒是听准了。”\n\n你笑着点头。他没有借共事催另一种意思，公事之外也仍可有一段真正喜欢的曲子。该回府时，他照自己的日程告辞。"},{"id":"distance","label":"听完这一曲，依礼送他出园","effects":{},"bonds":{},"slight":null,"reply":"你说明曲谱之外仍依礼往来，今日听完便送行。允礼听懂，没有再用下回二字试探。\n\n笛声收住，他拂去袍角花瓣，向你行礼。你夸一处收音，他答得疏朗：“皇兄肯细听，臣弟便不算白奏。”\n\n那份欣赏没有被他当成另一次邀约，你也没有因为说清距离，便不许他保有自己的好曲。\n\n他带帖子出园，脚步不因告辞而迟疑。今夜回府做什么，仍是他自己的日子，不须拿被留住来证明值得。"}]},"R05-02":{"id":"R05-02","title":"共校旧谱","kind":"relation","actor":"C05","location":"御花园","body":"允礼带来两份谱，先不说哪份是自己的改法，只让你分别听。第一遍舒展，第二遍在中途收紧，你听到转折，不由抬眼。\n\n“皇兄选哪一个？”\n\n你说出偏爱的那段，他却摇头：“臣弟偏爱另一段。”\n\n园里伺候的人不敢接话。他也没忙着改口，将两页并排压在石上，指给你看为何留那半拍。你问其中一处，他先承认还没试稳，又不肯连其余都一并改掉。\n\n风掀走一页，他拾起石子压好，没有顺手抽掉与你意见不同的那张。那点分歧不像争胜负，倒是看彼此能不能把真正喜欢的东西说到末尾。\n\n门边的随从报过时辰，允礼应了一声。两种奏法都能校成字，却未必要拼成同一个答案；留下纸上的不同，也得留下各自回去的时间。\n\n他将笔递到石案中央，不往你手里塞：“这一处不顺，皇兄也写上。臣弟回府还要再试。”你望见他那一行旁，确实留着能容另一种说法的空白。","options":[{"id":"warm","label":"认真争一回，再把两种奏法都留下","effects":{},"bonds":{},"slight":null,"reply":"你请他再奏偏爱的那段，自己也指出听来不顺的一处。允礼想一会儿，认了半句：“这里可以再缓。”\n\n你们试过几回，谁也没将另一人的谱丢开。两张纸各压一枚小石子，他看见你留下的不同说法，反倒笑：“倒比原来有意思。”\n\n临走，他把两种节拍抄成校注，添上自己的批语。纸能带走，归府的时辰仍没有撤。\n\n下回翻页，能认出的会是两个人都亲口说过的话，不是谁为了讨好谁改掉的半拍。"},{"id":"work","label":"各写所长，一起校完这一页","effects":{},"bonds":{},"slight":null,"reply":"你们将分歧逐项写下，允礼讲依据，也听完你的判断。两份奏法各自留存，没有因御前偏爱便只准剩一种。\n\n“原来皇兄也有不肯让的地方。”他收纸时笑道。\n\n你答彼此一样，他便朗声笑过，将校注留在案边。园门报过时辰，他按期回府，再试尚未稳妥的那处。\n\n今日共同校完一页，公事与曲谱都能认真相商。没有私人许诺，仍留下了一份能看出彼此判断的成果。"},{"id":"distance","label":"只校曲谱，依时送他回府","effects":{},"bonds":{},"slight":null,"reply":"你请他把两种奏法都留成校注，也说清仍按原来的礼数往来。允礼会意，不将多听一遍解释成新的亲近。\n\n他将未同意的那一处照样写全，没有因为距离明确便只抄一个你喜欢的答案。你核过，两页一并收好。\n\n门边又报时辰，他起身告辞，只留一句曲中哪处还可再试，没替下一次相见定日。\n\n校注是今晚实际留下的，礼数也是。谱不必改得一样，人与人的边界也能说清之后照常相待。"}]},"R03-01":{"id":"R03-01","title":"凯旋私谈","kind":"relation","actor":"C03","location":"养心殿暖阁","body":"离开摆着军账的正殿，年羹尧才解开披风的扣。廊下没有旁人，他先望一眼宫门，像是在辨归来这一路究竟到了哪里。\n\n“皇上方才说的，臣都听见了。”\n\n他并未要翻回已经问过的账，只把手背那道新伤藏进袖边，问公事之外，你是否还有话想对归来的人说。\n\n“边关的人知道粮晚一天是什么滋味。臣也知道，查清总比藏着强。”他顿一顿，“只是臣不愿话到最后，只剩军功和疑账两种。”\n\n风将披风一角吹起。他笑得短，仍带着赶路的疲惫；不是拿辛苦求免查，也没预备好被留在宫廊谈伤。\n\n你记得从前有多少话总绕着试探走，真问到人时，反而只剩一句臣惶恐。此刻他没有先请罪，已是在等一个肯听的答复。\n\n他将那只伤手露出来，不再藏，却也不往前伸。旧日君臣的分量仍在，今夜愿说到哪里，需要你们亲口说清。\n\n廊尽头的人止了步。年羹尧仍望着你，等这几句从殿里带出来的话落到实处。","options":[{"id":"warm","label":"“先让朕看看，你这一程过得怎样。”","effects":{},"bonds":{},"slight":null,"reply":"“朕看见你回来了。”\n\n年羹尧的目光定住。你问那道伤，也问归途中哪一夜睡得最踏实，等他说完才接着讲账仍须查。\n\n他低头拢好披风：“这句，臣记着。”随后主动补一处报销口径，连原簿应向谁取都说清，没有拿方才的问候换免查。\n\n走回殿前，你们将未说完的话留在这段宫廊。归人被看见，公事也还在；这一刻他肯把疲惫说给你听，已经与只报捷不同。"},{"id":"work","label":"把战功与账目分别说清","effects":{},"bonds":{},"slight":null,"reply":"你把战功与账目分别说清，不以亲疏替代原凭，也不因查账抹去已经报明的功。\n\n年羹尧听见两份都被认真接住，神色先松一些，指出尚须原件的那处，不为了当场交差就把未亲见的认下。\n\n“这样讲，臣听得明白。”\n\n你再问经手，他便将去向讲完。没有私下的许诺，仍有能共同核清一件事的信任。他重新扣好披风，这回回殿的脚步不必带着方才那句试探。"},{"id":"distance","label":"说明君臣分寸，公私分别核查","effects":{},"bonds":{},"slight":null,"reply":"你说明今后仍以君臣相待，功绩与军账都据实核验，私下不再另许他意。\n\n年羹尧静一瞬，站直扣好披风：“臣领会。”他没有再问那道伤，只把原簿和经手去向交代完整。\n\n你听完，照样让他将未核之处留白，没有拿拒绝私情去削他应有的功。\n\n转身前，他行了完整的礼。疲惫仍在，界线也落定；公事能继续问，私人试探到这里便收住，不当成谁犯下的过错。"}]},"R03-02":{"id":"R03-02","title":"边书","kind":"relation","actor":"C03","location":"西北来信","body":"信从西北来，封口沾着一点细沙。年羹尧先写粮道，再写轮调，几处数字旁特意留了原簿所在，并未将待核的写成已经办妥。\n\n末页的字迹才慢下来。他说新来的马认路慢，连营门都能跑错；又说昨夜风大，帐门响得像京里的更鼓。末了另起一行，问御案上的舆图是否还摊着。\n\n你把信移到灯下。那行字边有一道擦过的墨，写信的人似乎想补几句，最后仍从一件看得见的东西问起。\n\n案上另有待签军务，纸色与来信很像。你把两份分开放，取一张新纸。写公事或写近况，笔都要从你手里落下，不能替远处的人先接完后半句。\n\n窗外也起风了。你无从知道他此刻是否已经睡下，只看见信上确实写来的几件事。那道伤该不该再问，私下的试探怎样回应，都能留在不同的纸里。\n\n苏培盛在门边等封。你将信尾那点细沙拨到一旁，蘸墨，先让军务的原页留在自己认得的位置。","options":[{"id":"warm","label":"写一封只谈近况的私信，问问他的伤","effects":{},"bonds":{},"slight":null,"reply":"你在私信里答舆图仍摊着，也写京里的风，问那道伤可曾好全。\n\n落到末页，你将最初嫌太直的几个字留下：下回不必只等有军报才写。军务另封，这一页没有一笔赏银，也没替他预备该怎样答。\n\n封口压好，信交给驿使。那点细沙还留在案边，你没有立刻拂去。\n\n写下关心的是你，远处的人还要实际收到。灯照着空下来的纸面，他的后半句话，仍留在下一程路上。"},{"id":"work","label":"军务另列，也答他舆图仍在","effects":{},"bonds":{},"slight":null,"reply":"你逐项回复军务，将待核数字另列成页；信尾关于舆图的问题，也答还在，看得到西北那条路。\n\n这句问候没有改掉前面任何一笔账。你把两份纸分开封好，让递信的人照原次序交驿，未把一份清楚的公务回函写成双方另有约定。\n\n纸上既有他能接着核的差事，也有能收到的平实回应。\n\n风在窗外停了一阵。回信已写成，尚未送到的意思不先结成他的答复，后续仍沿原驿程等。"},{"id":"distance","label":"依军务回信，留下平实问候","effects":{},"bonds":{},"slight":null,"reply":"你按军务回信，末页问一句将士起居，关于舆图也如实答仍留在案上。\n\n私下那点试探没有被接成新的许诺，也没有被当作过错略去他该收到的公务答复。两封各归其处，你用镇纸压住西北一角，核好封口再交驿使。\n\n他不必猜这封信是否另有暗语，你也没有借一次回函改变应有的待遇。\n\n眼前留下的是清楚的分寸和寄出的纸；远方的反应还没来，今夜不替他写完。"}]},"XR09-01":{"id":"XR09-01","title":"名字之外","kind":"extension","actor":"C09","location":"碎玉轩","body":"碎玉轩的窗开了半扇，风将案上一页诗笺翻起。甄嬛伸手压住，先将茶挪远，怕水印落在纸上。\n\n“这句，臣妾原先觉得是惜别。”她指着末行，“今日再看，却觉得写诗的人未必肯留。”\n\n你说起另一种读法，她没有立刻应声。窗外有人走过，她等脚步远了，才问：“若臣妾读得与皇上不同，这一页还许留着么？”\n\n纸上并没有御前的题字，也没有为了迎合谁而重描的笔画。她将笔搁在自己的那一侧，留下一小块空白，既没有催你填，也没有代你写。\n\n你可以问她为什么改了想法，也可以只把今天当作一次读诗。殿前的接见已有名册与礼数；眼前这个人怎样看一句诗，却还得听她自己讲。\n\n她把那页纸转向你，笑意比方才轻快了一点：“若皇上只想听一句相同的话，臣妾便不必把这半日的疑问拿出来了。”\n\n案边的茶正好入口。她等的是你对这句话的回答，不是另一道赏赐。","options":[{"id":"develop","label":"听完她不同的读法，愿意慢慢了解","effects":{},"bonds":{},"slight":null,"reply":"你没有急着往空白处题字，先问她为什么改了读法。\n\n甄嬛将前一句也指给你看：“若只剩舍不得，后面便不该写得这样干净。”你仍有不同的看法，却没有让她重写。她把两种意思各说了一遍，笑道：“原来同一页纸，也容得下两个答案。”\n\n你说愿意慢慢了解她。她将纸收回自己面前：“那便先记得，臣妾今日没有同意这半句。”\n\n她愿意让你听见自己的想法，没有因此答应私情。临别时，她提起还有一首想读的诗；具体哪日再谈，仍要另行商量。"},{"id":"cooperate","label":"只以诗相交，把私情的距离说清","effects":{},"bonds":{},"slight":null,"reply":"你把自己的读法说完，也说明往后依礼来往，私情不另许诺。\n\n甄嬛捏着纸角的手松开了些：“那臣妾倒不必为每一句话猜另一个意思。”她把不赞同的地方讲得更细，仍没有改成你的答案。\n\n你们各自留下对末句的解释，没有合写一份假装一致的题词。她收好诗笺，说下次若谈诗，仍可直说哪里不喜欢。\n\n门外有人候她，她依自己的时候告退。今天有清楚的距离，也有一段说完整的话；没有谁欠下一个往后必须亲近的答复。"},{"id":"unsure","label":"坦言尚未想定，不请她等候","effects":{},"bonds":{},"slight":null,"reply":"你说自己眼下尚未想定，不能为了留住今日的好意，请她替你等候。\n\n甄嬛没有急着接一句宽慰。她把那页诗翻到背面，才说：“那臣妾也不必先给一个答案。”\n\n后半盏茶仍能喝完。她谈起另一种断句，你听出她并非故意与你相反，只是不愿把不确定的事装成已经想通。\n\n告退前，她将诗笺放回自己的书里。今天没有约期，没有借礼物续上的许诺；若以后再谈，要从两个人届时真正愿说的话接起。"}]},"XR09-02":{"id":"XR09-02","title":"不作旧影","kind":"extension","actor":"C09","location":"碎玉轩","body":"那件新衣已经收起，甄嬛今日穿的是自己挑的寻常颜色。案边仍留着空白笺，她没有先拿诗来试探，只请你坐下。\n\n“暖阁里的话，臣妾听见了。”她将茶盖轻轻放稳，“可不拿臣妾与旧人相比，与愿不愿同臣妾来往，终究是两件事。”\n\n风吹动窗上的细格影，落在她的袖口。她没有换一个更讨喜的问法，也没有把今日的到来当作已经等到的答复。\n\n你想起第一次读诗时，她不肯随口改掉的那半句。若只要一个相同的答案，便连此刻的不同也看不见。她想知道的不是自己能比谁更好，而是往后说出不同的话，会不会又被要求照着别人的模样活。\n\n“若皇上无意，臣妾可以听明白；若尚未想定，也不必借旁的事替这句话。”她停了停，“只是臣妾如何答，还请容臣妾自己想。”\n\n茶在两人之间慢慢散着热气。今日可以说清一件事，却不能将过去没回答的话改成从来没有发生。她留着自己的决定，你也须对眼前说出的每一个字负责。","options":[{"id":"develop","label":"具体回答旧影，愿意继续了解本人","effects":{},"bonds":{},"slight":null,"reply":"你把话落在眼前：“朕想知道你为什么喜欢这句，又为什么会改。不是要你照谁的样子来。”\n\n甄嬛没有因这一句便将手递来。她问：“若以后臣妾的答案仍不合皇上心意呢？”\n\n你说那便听她说完，意见不同可以再谈，不用赏物遮住问题。她看了看案上空白的纸，仍把笔留在自己手边。\n\n这一次，你说的是愿意继续认识她，而不是宣布她已经爱上你。"},{"id":"cooperate","label":"尊重她本人，也清楚说明无意私情","effects":{},"bonds":{},"slight":null,"reply":"你说明，不拿她与旧人相比，也不愿让礼遇继续被误当成私情许诺。\n\n甄嬛安静了一会儿，没有立刻笑出来。“这句话，臣妾听清了。”她端起茶，喝过才又开口，“往后谈诗，臣妾仍有自己的意思；应有的礼数，也不必因今日的话另作轻重。”\n\n你应下。她将窗开大了一点，说近日想把几页散稿理在一起。那是她自己的打算，不等一份御前的心意才开始。\n\n旧影之外，她仍有自己的名字。今日的距离有了清楚落款，往后不必将每次依礼相见都写成等待回心。"},{"id":"unsure","label":"说明尚未确定，不拿礼遇代替答案","effects":{},"bonds":{},"slight":null,"reply":"你说尊重她本人，却不能把未定的心意说成已经有了归处，更不该让她替一句模糊的话等候。\n\n“臣妾也未曾答应等。”她的声音不高，却没有让这句话含混过去。\n\n你们把暖阁里的两件事分开：她不是旧人的影子，往后是否亲近仍须两个人各自回答。她可以继续读诗、见朋友，也可以改日不想谈这一件事。\n\n茶喝到一半，她合上杯盖。今日不添赏物，不替彼此作决定；原先说过的话仍留着，新的回答也只写到这里。"}]},"XR10-01":{"id":"XR10-01","title":"一页实账","kind":"extension","actor":"C10","location":"宫中茶室","body":"茶室的窗下摆着一盆菊。沈眉庄先将盆转了半寸，让新开的那一面朝向光，才把薄薄的一页纸推到案中。\n\n“同样写着冬衣份例，这里与另一页却不是一个数。”她没有圈出谁的名字，“可能抄错，也可能另有补领。没有原簿，臣妾不敢说是谁多拿了。”\n\n你问她是否愿接着清点。她手指在纸边停了一下，抬眼道：“这页是臣妾看见的，愿意说明。另接一册长差，今日不愿。”\n\n这句话说得平稳，既没有拿劳累讨赏，也没有为拒绝另找一个更好听的由头。她将原纸交回，让你按已有公事渠道送掌册处核对，注明疑点出自她，不把疑点写作查明的罪责。\n\n“若只有答应接差才能说问题，往后怕是谁也不肯多看一眼。”\n\n她说完才低头续茶，杯里的水已不算热。你看见窗下的花，又想起她方才为花转盆的小动作。眼前的人不只会看账，也有自己想留的半日。\n\n她愿意听你的回答。那页纸须照证据走，私人来往却仍是另一件可以各自选择的事。","options":[{"id":"develop","label":"听完疑账，再问她自己的生活","effects":{},"bonds":{},"slight":null,"reply":"你将疑点另纸写明，交掌册处按原簿复核，留下沈眉庄指出问题的来源；没有顺手把整册差事压回她案上。\n\n“这一册另循职掌办理。你愿说明的这一页，便只是一页。”\n\n她这才把手收回，问你要不要换一盏稍淡的茶。你没有接着问账，而是问那盆菊为什么朝窗。\n\n“那边新开了两朵，若只照着人看，反倒背了光。”她说着笑起来，讲起自己昨日搬了两次都不满意的事。你说愿意慢慢了解她，她没有就此许诺，只将花盆留在自己选的位置。\n\n这次有公事该走的渠道，也有一件她愿意说的小事；她拒绝的额外差事没有变成新的命令。"},{"id":"cooperate","label":"公事依证据，私情明确只合作","effects":{},"bonds":{},"slight":null,"reply":"你将疑点和提出者一并记下，交掌册处依原簿复核，不因尚未查明便定谁的罪，也不将新增长差交给她。\n\n你说明私下只以可信同事相待，不另许私情。沈眉庄听完点头：“那臣妾若说哪一页不妥，便不必再猜这句话是否不近人情。”\n\n她仍把自己知道和不知道的部分各说一遍，没有少讲，也没有换一句讨好。原件交还后，她起身将窗下的菊转正，指着新花问你觉得颜色浓淡怎样。\n\n你们可以各有喜好，也可以把一页账认真谈完。她的署名、份例与拒差的分寸，未因不谈私情而打折。"},{"id":"unsure","label":"私话暂缓，疑账仍交原簿复核","effects":{},"bonds":{},"slight":null,"reply":"你承认自己的心意尚未想定，不请她等候一份模糊答复。那页疑账却不能因此搁在私人的约期里：你将原件交掌册处，记明提出者，按原簿复核。\n\n沈眉庄说明今日不愿接新增长差，你应下，让它另循现有职掌办理。\n\n“公事不是为等一句私话才开始的。”她说。你没有把这句话听作催促，也没有用添赏代替回答。\n\n她把茶喝完，提起自己还要照看窗下那盆菊。今日谈到这里，她有自己的日程；未定的私话和待核的账，各自保留真实的进度。"}]},"XR10-02":{"id":"XR10-02","title":"茶凉仍谈","kind":"extension","actor":"C10","location":"宫中茶室","body":"今日案上没有账本，只有两只茶杯。沈眉庄没有把上一回指出的疑点说成已经办好的功劳，先说明原簿复核还欠正式回音。\n\n“臣妾记着那页纸，也记着皇上曾问，愿不愿再接一册。”她把茶向你推近，“今日想问的，却不是那册账。”\n\n你示意她说。她停了片刻，才道：“皇上夸人勤勉时，有时像是已经替人答应了下一件差事。受夸的人若说不，便仿佛辜负了这份看重。”\n\n这话并不顺耳。你原想解释自己只是信任她，她却没有抢着说谢恩：“信任，也该容臣妾挑一挑能做的事。臣妾会尽力，不等于所有空闲都该等着御前。”\n\n茶面已不再冒热气。她尝了一口，笑说淡了也能喝，浓淡总不必每回一样。那点笑意并没有将先前的批评收回，只是让不同意见之后仍有地方坐下。\n\n窗外一阵脚步过去。她没有为这次小坐空下整日，稍后还有自己的去处。是否愿在公事之外再了解彼此，可以今天说，也可以今天不答；她仍保留自己的意见和时间。","options":[{"id":"develop","label":"承认她能批评也能拒差，愿再了解","effects":{},"bonds":{},"slight":null,"reply":"你承认，夸人勤勉时常忘了再问一句愿不愿。\n\n“若朕又把看重说成了加派，你可以当面指出。那页账依证据复核，不靠你答应更多差事来证明诚意。”\n\n沈眉庄没有接一句处处妥当：“皇上今日肯听，是一回事；下回仍肯听，又是另一回事。”你将这句批评也听完，才问她是否愿在没有差事时继续来往。\n\n她把杯盖搁到一旁。你问的是她个人的心意，不是请她为御前的安排再添一项应承。"},{"id":"cooperate","label":"接受批评，私下仍只做可信旧友","effects":{},"bonds":{},"slight":null,"reply":"你承认她指出的偏私，也说清私情仍只到可信旧友的分寸。\n\n“往后要问差事，便先问愿不愿；要说功劳，就照实际办成的记。两件都不拿今日的话作交换。”\n\n沈眉庄没有将批评收回，却舒展了些：“这样，臣妾便不必把每句真话都绕到茶凉。”她尝了一口，又笑说今日已经凉了，倒不必为了好听改口。\n\n你们把余下的茶喝完。待核的账仍待回音，她拒绝的差事仍没有被强加，今后也不必拿多做公事来换一份私下亲近。"},{"id":"unsure","label":"解释自己的想法，私情仍待想清","effects":{},"bonds":{},"slight":null,"reply":"你解释，当时是看重她细心，并非想占去她所有空闲；但也承认自己确实没有先问愿否。\n\n沈眉庄听完，仍有不同看法：“好意若不先问，也可能成了旁人的负担。”她没有被这番解释说服，你没有要求她将不同意见换成谢恩。\n\n私情眼下仍未想清，你不请她等候。她也说明，自己不会为这份未定放下原来的去处。\n\n那页账按已留的渠道继续，不能因为今日没谈拢便撤回问题。她将杯放稳，约定的只有今后问差事时先问一句；没有新的恋爱承诺。"}]},"G01":{"id":"G01","title":"查亏空","kind":"government","actor":"C28","location":"养心殿御案","body":"张廷玉将原簿和副册错开半页，露出两种不同的装订线。新页上的数能对齐，旧页上的押却少了一个。\n\n“这笔经过三人，最后只剩一人认账。”他指着纸缝说。\n\n地方书吏候在门外，另外带了铺户的缴单。有人急着将缺口压成一个名字，有人怕追到自己经手那一日。你记得前世的结局，眼前却仍须从能对照的凭据起笔。先听哪份、先追哪一处，会决定下一张单子往哪里送。","options":[{"id":"records","label":"先核原始账据","effects":{"execution":2},"bonds":{},"slight":null,"reply":"你让原页与副册逐笔相对。张廷玉先抽出有原凭的三张，将缺押的压在另一边，没有用一句总数无误盖过去。\n\n纸上出现能继续问的具体日期。书吏回话不再只说照例，从哪只柜里取原件，也终于说清了。"},{"id":"local","label":"听地方与百姓的两份说法","effects":{"people":2},"bonds":{},"slight":null,"reply":"铺户的缴单与地方的回话分别读完。两份说法不合处，你让张廷玉原样标出。\n\n门外的人以为还要再背一遍好听的，听见你问米铺何时不肯赊，才低头从袖中取出另一张日期更早的单。"},{"id":"scope","label":"列清经手责任与待查项","effects":{"stability":1},"bonds":{},"slight":null,"reply":"你将经手、签核、待取原件分成三栏，未见的押暂且空着。张廷玉核过，另列传问的人，不让同一个人既作证又替别人代答。\n\n缺口没有因列清而消失，却已有了每一步该向谁问的去处。"}]},"G02":{"id":"G02","title":"分期追缴","kind":"government","actor":"C28","location":"养心殿御案","body":"回款单压在案角，旁边一页写东街米价。张廷玉把两份分开：“钱能先回来一些，如何追，仍得写清。”\n\n催得紧，眼前数字会好看；经手若把旧欠转成铺户新缴，回访时也得敢承认。追得慢，地方能周转，余下缺口却还挂着。\n\n你翻到最初圈过的县名，问有凭的到底是哪几笔。笔停在期限一栏，门外等着取走的不是一句宽严得当，而是一道能照着办的批示。","options":[{"id":"phased","label":"分期追缴，留足周转","effects":{"treasury":4,"people":2},"bonds":{},"slight":null,"reply":"你把各期与周转底数写在同一页，张廷玉复述过，再将首批回单收进原册。\n\n余欠仍列着，东街铺户这一期不必先卖农具补足经手人的旧窟窿。你让下一份回报连新缴单一起带来，看看批示有没有真正落到那条街。"},{"id":"strict","label":"限期足额追缴","effects":{"treasury":8,"people":-4},"bonds":{},"slight":null,"reply":"期限落笔，首批回单很快摆到案前。张廷玉收好数字，也把米价那页留在最上头。\n\n“下回要问，这笔钱从谁手里来。”他道。你没有将那页撤走；眼前回得快是实情，地方怎样承受，仍得让后来的回访回答。"},{"id":"review","label":"先追有凭据部分","effects":{"treasury":2,"execution":2},"bonds":{},"slight":null,"reply":"你将有原凭的几笔先圈出，缺押的暂不混入。张廷玉把首批回单夹好，逐名写上还要取来的原件。\n\n钱回得少些，哪些已经核过却清清楚楚。米价一页留在册边，下一次既要看旧欠，也要看这份审慎有没有被下面改成另一种催缴。"}]},"G03":{"id":"G03","title":"复核县库","kind":"followup","actor":"C28","location":"养心殿御案","body":"县里回来的纸不甚整齐，一页有水痕，一页折着米铺的赊账记号。张廷玉先翻到上回圈过的那条街。\n\n“库账在前，铺户的缴单在后。”\n\n你把原批取出来，先对日期，再对经手的落款。能收回多少，执行那日已记过；今日更要看钱回来以后，那些照常开门的人家，日子有没有被挤出新的缺口。","options":[{"id":"review","label":"阅核回访，保留实际结果","effects":{},"bonds":{},"slight":null,"reply":"你将县库与铺户两边都核完，才在回访页落款。张廷玉没有只抄好看的总数，那几处能继续周转、那几处仍要追问，都留在同一册里。\n\n原来的批示因而有了真正的后文。"}]},"G04":{"id":"G04","title":"军需册中的重复支领","kind":"government","actor":"C03","location":"养心殿御案","body":"年羹尧把西北催粮的信推近，另一只手按着同批两笔支领的副册。“核账臣不拦，前营等不了那本原簿慢慢走。”\n\n张廷玉翻到日期相同的一行：“所以出仓和原凭都得留。先拨多少，可以定；这两笔不能便算核清。”\n\n你望着舆图上从转运到前营的一段细线。纸上的先后，到了路上就是实际几日。拨款、核账与消息传给谁，可以分别写明，不必在全信与全疑之间只选一个说法。","options":[{"id":"emergency","label":"先拨8点，联合核账","effects":{"treasury":-8,"defense":3,"stability":1},"bonds":{},"slight":null,"reply":"你将先拨的数写下，请两边分别记出仓与取原簿。年羹尧看过前一行，随即指出转运要问的人；张廷玉将名字补在副册边。\n\n第一步可以走了，待核的两笔也仍有人追。"},{"id":"pause","label":"暂停拨款，限期重报","effects":{"defense":-4,"execution":2},"bonds":{},"slight":null,"reply":"你让暂缓拨款的批示与催原簿的文书一并发出。年羹尧读罢，指尖仍停在催粮信上。\n\n“缺粮这一段，也请原样记。”你让经办照录。核验有了明确去处，等待所带来的损失却不会因此省去。"},{"id":"full","label":"全额拨12点，豁免审核","effects":{"treasury":-12,"defense":4,"execution":-3},"bonds":{},"slight":null,"reply":"足额拨款的字写定，免审的那行也留在原页。年羹尧领命办补给，张廷玉将未核副册夹回去，没替它盖一个查清的押。\n\n眼前的粮可以走，后来回访仍得面对这页没有原审计的空白。"}]},"G05":{"id":"G05","title":"整顿粮道","kind":"government","actor":"C03","location":"养心殿御案","body":"钱款已有前账，转运的交接单却又递了回来。年羹尧指着图上一处：“这里换车，也换经手。漏一名，到了前营便要再问一回。”\n\n押运、凭册逐营签领，或由现任军需官照章办，各有能先接住的一段。你将拨款那页留在案边，不让同一笔钱在新单上再走一次。\n\n这次要签的是粮怎样走、途中谁来认、到人后拿什么回来。笔一落，车在路上的日子才真正开始。","options":[{"id":"escort","label":"设押运并核发到人","effects":{"treasury":-2,"defense":2},"bonds":{},"slight":null,"reply":"你将押运与到人签领接在同一份交接单上，先对过已经付下的账，再让经手逐名认领。\n\n年羹尧看过最后一栏，补上前营回执该从哪里寄。案上有了车从何处启程的第一处落款。"},{"id":"ledger","label":"凭册交接，逐营签领","effects":{"treasury":-1,"execution":2},"bonds":{},"slight":null,"reply":"你将逐营签领册样式留好，要求每段交接都对上姓名。经手人复述时漏了一处转运，你请他翻回再念。\n\n册子终于能照着用，回来的每一页也有原样可核，不必等粮走远了才重新猜哪段该谁答。"},{"id":"local","label":"由现任军需官执行，保留复核","effects":{},"bonds":{},"slight":null,"reply":"你让现任军需官依职分领下转运，原来的复核范围照录在后。年羹尧核过去向，没有将一声领命说成全程已经平安。\n\n差事从案上交出去，下一封要看的，是经手怎样把这一批粮交到人前。"}]},"G06":{"id":"G06","title":"验收军纪","kind":"followup","actor":"C03","location":"养心殿御案","body":"三份回执抵京，纸角沾的尘色各不相同。出仓的一页最早，转运的一页换过经手，前营那页签着实际领粮的人名。\n\n你先按日期摆好，再翻最初圈过的两笔支领。案边没有报喜的长句，经办将仍缺的原凭也夹在旁边，等你一起看。\n\n粮有没有到、人怎样领、原账查到哪里，今日终于能分别回答。每一项都要回到原来那道批示上，才知道这一程究竟改变了什么。","options":[{"id":"review","label":"阅核粮道与领粮回执","effects":{},"bonds":{},"slight":null,"reply":"你从出仓一路核到领粮，将同名与漏签处都问过，才收下这轮回执。远处几行不甚整齐的字，比当日那道朱批多走了一程。\n\n该留的风险仍夹着，真正办到的这一批，也有了自己的落款。"}]},"P01":{"id":"P01","title":"敬妃交班","kind":"side","actor":"C11","location":"养心殿御案","body":"敬妃把三张交班单排在案边，第三张上留着两处同样的空白。\n\n“这一处等那边签，那边又说归这里。”她指给你看，“人手未必少，只是出了事，最后总是端东西的人赔。”\n\n她没有替谁讨一个好听的名目，只将交出去的钥匙、接手的册与签核的人分别列明。若今日仍只添齐姓名，明日碰上要担责的一项，三张纸还会照旧转回来。\n\n敬妃把笔搁在空白旁，等你决定这一回要写到哪一步。","options":[{"id":"act","label":"写清交接人与签核权","effects":{"palace":3,"execution":1},"bonds":{},"slight":null,"reply":"你把交接人与签核权逐项写清，敬妃先问遇到两处都管的事向谁呈，再把那个人名留在页边。\n\n钥匙与册子终于能朝同一处交，不必让下头的人捧着空单来回跑。她收好三张纸：“这样再换人，也知道该照哪一行。”"},{"id":"pilot","label":"先补名册，权限另议","effects":{"palace":1},"bonds":{},"slight":null,"reply":"名册先补齐，敬妃照原来经手将钥匙点明，却仍把待定的签核处折起一个角。\n\n“今日能交的先交，遇上这几项，臣妾还得来问。”你让她留着折角。混乱少了一层，担责的口径尚未全定，没人替它写成已经完备。"},{"id":"delay","label":"暂缓交班，保留问题","effects":{"palace":-1},"bonds":{},"slight":null,"reply":"敬妃将未定的三处原样夹回，没有让接班人先签一份自己担不起的单。\n\n钥匙暂不换手，旧管事仍须继续守。她告退前看一眼案边：“等皇上再问，还是这几处。”问题留了下来，等待也真落在仍未交班的人身上。"}]},"P09":{"id":"P09","title":"颂芝报忧","kind":"side","actor":"C19","location":"养心殿御案","body":"颂芝进来时先向门边看了一眼，才把叠得很小的起居纸展开。纸上有两次添茶的时辰，后面都没有写睡下。\n\n“小主怕传出去，又成了使性子。”她说到这里，自己先低下头。\n\n你没有让她把难眠换成一切安好。她才补上夜里那句嫌灯晃眼，还有清晨起来不愿多说的疲惫。这些能说明不适，尚不能替医官定因。她等着听，今日如实说来的坏消息，会被送到哪里去。","options":[{"id":"act","label":"允许如实报告，安排复核","effects":{"health":2,"palace":1},"bonds":{},"slight":null,"reply":"你请她按原时辰留记录，照常安排复核，话只交给该照护的人。颂芝把两处潦草的字又补清，没有添一句小主其实无事。\n\n她临走终于抬起头：“那往后真睡不好，奴婢也这样报。”纸上的不安有了可接住的去处，原因仍待医官核。"},{"id":"pilot","label":"先照护，再追问原因","effects":{"health":1},"bonds":{},"slight":null,"reply":"你先交代灯火与起居照护，请她把那两夜继续记清。颂芝将纸收稳，问下一回该何时呈，你给她留了再说的口。\n\n今夜先让人少受一点烦扰，难眠的来由却还没问全。她没有因此把未答的问题划去。"},{"id":"delay","label":"只收下记录，暂不处置","effects":{"palace":-1},"bonds":{},"slight":null,"reply":"你收下起居纸，暂未安排新的处置。颂芝等了片刻，才依礼退到门边。\n\n“那奴婢仍照原样记着。”她说。记录终于留下，夜里的不适也还在；这份克制没有被她当成照护已办妥的答复。"}]},"P10":{"id":"P10","title":"宝鹃传话","kind":"side","actor":"C20","location":"养心殿御案","body":"宝鹃复述家书，末尾一句比原纸少了几个字。你请她重新从那行读起，她的声音便慢下来。\n\n“奴婢只是不想小主忧心。”\n\n她把原信握得紧，仿佛不说出来，那件为难的事便不会落到安陵容手里。桌边的曲谱还摊着，那个人自己要回怎样的一封信，却得先知道家里究竟说了什么。\n\n你将原文与转述放在两边。问缘由、改传话的办法，或暂且照旧，都会决定下一句由谁替谁选。","options":[{"id":"act","label":"让安陵容看原文，核对转述","effects":{"execution":2,"palace":1},"bonds":{},"slight":null,"reply":"你让原信先交还安陵容，转述不同的两处另外标清。宝鹃想再解释，你请她把缘由留待本人听完再说。\n\n家书不再只剩一份筛过的意思。如何回、愿意说到哪里，终于能回到收信人的手里。"},{"id":"pilot","label":"先询问转述缘由","effects":{"palace":1},"bonds":{},"slight":null,"reply":"你先问那两处为何省去。宝鹃说怕责怪，也怕小主伤心，原来两种顾虑混在了一句为她好里。\n\n你让她原样记下，原信仍压在案边等后续核对。话头打开了，传递办法尚未全部改定，不能当作本人已经看全。"},{"id":"delay","label":"暂保留旧传话方式","effects":{"palace":-2},"bonds":{},"slight":null,"reply":"你暂留原来的传话方式，仍将原文收好。宝鹃应下，手却又按在折角，像在等还需不需要那几个被省去的字。\n\n她退下以后，两份纸仍有不同。暂缓没有替安陵容选回信，也没让被筛掉的原话自动回到她手中。"}]},"P11":{"id":"P11","title":"卫临留案","kind":"side","actor":"C22","location":"养心殿御案","body":"卫临送来一份脉案副本，最上头的病名用另一张纸盖着。接班的医官常要重问一遍，他想让核过的诊见留得住。\n\n“可谁都能翻，也不成。”他说，指着查阅一栏。\n\n你看见他把诊治所需与无关的私话分在两页。留给后来的人，不该变成让更多人知道一个病人的难处；只锁在一人手里，又会在轮值换人时重新断开。\n\n他将副本转正，等你决定哪只手能接、接过以后该留下什么凭据。","options":[{"id":"act","label":"留档并分清访问权限","effects":{"health":2,"execution":2},"bonds":{},"slight":null,"reply":"你将轮值诊治的查阅范围写清，借阅与归还另留签名。卫临把无关私话的那页收起，只让后来的医官从所需诊见接着看。\n\n案能留，人不必每次重说一遍，也不因留档便成了满宫都能翻的谈资。"},{"id":"pilot","label":"先试行轮值医官查阅","effects":{"health":1,"execution":1},"bonds":{},"slight":null,"reply":"先试给轮值医官查阅，卫临将每次取还列成小单，暂未把旁的用途放进去。\n\n“先看看交班时少漏哪一句。”他把这一句记在册边。接手有了开始，范围仍须在试行后核，不能以一份副本便说制度全成。"},{"id":"delay","label":"仍由一人保管","effects":{"execution":-1},"bonds":{},"slight":null,"reply":"你仍交由一人保管。卫临将副本包回去，原案未散，轮值要问的那一处却还得另行传话。\n\n他应了，仍把查阅空栏留在原纸上。谨慎护住了案，也留下接手不便的代价，今夜没有将两件事一起说成已解。"}]},"K01":{"id":"K01","title":"七夕两宫","kind":"dilemma","actor":"C07","location":"翊坤宫","body":"七夕前一日，两道帖子前后脚递到御案上。\n\n头一道是翊坤宫的。年世兰亲笔，字写得飞扬：今年七夕，翊坤宫备了巧果、新戏，还有她亲手扎的一盏鹊桥灯，请皇上务必赏光。末尾添了一句——“停香以后，臣妾总睡不好。皇上来坐坐，臣妾便睡得着了。”\n\n第二道是景仁宫的，规规矩矩的楷书。宜修说，七夕乞巧向来是中宫领着六宫拜月，礼部单子都拟好了，请皇上照例驾临。她一句私话也没写，可那只玉环才送出去没几日。\n\n苏培盛捧着两张帖子，不敢替你分先后。\n\n“皇后那边是祖宗规矩，”他小声说，“华妃娘娘那边……娘娘停了香以后，人确实清减了些。”\n\n两处都在等你。七夕只有一夜。","options":[{"id":"empress","label":"依礼去景仁宫，陪皇后拜月","effects":{"palace":2},"bonds":{"C06":{"trust":4,"safety":2}},"slight":"C07","reply":"景仁宫的月台上摆着香案，六宫的人跪了一地。宜修领着拜月，礼数一丝不错。\n\n拜完了，人都散了，她才走到你身边，很轻地说了一句：“臣妾以为皇上不会来。”\n\n你说规矩在这里。她点点头，没再说什么，只是那只玉环，在月光底下亮了一下。\n\n翊坤宫那边，听说灯点了一夜。"},{"id":"consort","label":"去翊坤宫，看她扎的那盏灯","effects":{"palace":-2,"mood":1},"bonds":{"C07":{"trust":4,"safety":2}},"slight":"C06","reply":"翊坤宫的院子里挂着那盏鹊桥灯，扎得歪歪扭扭的，桥身一边高一边低。\n\n年世兰看见你，先是愣住，随即扬起下巴：“臣妾就知道皇上会来。”可她的眼圈是红的。\n\n那一夜她睡得很沉。你守到后半夜才走，出门时听见景仁宫那边传来散场的钟声。"},{"id":"both","label":"先去拜月，再去看灯，两处各坐半夜","effects":{"health":-3,"palace":1},"bonds":{"C06":{"trust":1},"C07":{"trust":1}},"slight":null,"reply":"你先去了景仁宫，陪宜修拜完月，又匆匆赶去翊坤宫。到的时候已过子时，那盏鹊桥灯还亮着，年世兰却已经歪在榻上睡着了。\n\n你在灯下坐了一会儿。回宫的路上，夜风一吹，你咳了好几声。\n\n第二日两宫都派人来谢恩，谢得都很周全。只是两个人，都只等到了半个你。"}]},"K02":{"id":"K02","title":"再唱一回","kind":"dilemma","actor":"C08","location":"御花园","body":"宫宴过去三日，安陵容托宝鹃递来一张纸条，字写得极小，改过好几处。\n\n她说，那日的曲子没唱完，她心里一直搁着。元宵的灯宴，她想求皇上恩准，当着众人，把那支曲子从头唱一遍。\n\n“臣妾不是要争什么，”纸条最后写，“只是想让那支曲子有个结尾。”\n\n你还没回话，翊坤宫的颂芝也来了。华妃娘娘听说了这事，让她带一句话：那日席上的话，是娘娘说的，娘娘认；可若安答应要当着六宫再唱一回，那便是当众打翊坤宫的脸。“娘娘说，皇上若准了，元宵灯宴她就不去了。”\n\n两个人，一支曲子。","options":[{"id":"stage","label":"准她在灯宴上唱完","effects":{"palace":-1,"mood":1},"bonds":{"C08":{"trust":4,"safety":3}},"slight":"C07","reply":"元宵灯宴，安陵容穿了一身素净的衣裳，站在灯下，把那支曲子从头唱到了尾。\n\n唱到上回停下的那一句，她的声音抖了一下，没有停。\n\n满座的人都在听。翊坤宫的位置空着。你看见宜修往那个空位上看了一眼，又收回目光。\n\n散了席，安陵容在廊下给你磕了个头，什么也没说，可那一下磕得很重。"},{"id":"spare","label":"不准，曲子另找机会","effects":{"palace":1},"bonds":{"C07":{"trust":3}},"slight":"C08","reply":"你让人回了安陵容，说灯宴另有安排，曲子以后再唱。\n\n宝鹃回来说，小主听了，只说了一句“臣妾明白”，便关上了门。\n\n元宵那夜，年世兰来了，坐在你下首，谈笑如常，还替你挡了两杯酒。安陵容的位置在很远的地方，你始终没看清她的脸。"},{"id":"private","label":"请她到御花园，只唱给你一个人听","effects":{"mood":-1},"bonds":{"C08":{"trust":2},"C07":{"trust":1}},"slight":null,"reply":"那日午后，御花园里没有旁人。安陵容站在海棠树下，把那支曲子唱完了。\n\n她唱得很好，比宫宴上那回还好。唱完了，她低头站着，等你说话。\n\n你说唱得好。她笑了一下，笑得很懂事：“谢皇上。”\n\n可她要的不是只唱给你一个人听。她知道，你也知道。只是这一回，没有人的脸被打着。"}]},"K03":{"id":"K03","title":"庆功与笛约","kind":"dilemma","actor":"C03","location":"太和殿偏殿","body":"年羹尧凯旋的庆功宴定在四月十五。礼部的单子上，从申时排到子时：赐宴、颁赏、将士谢恩，最后是皇上与大将军对饮三杯——这是给西北将士看的，也是给满朝文武看的。\n\n单子送来时，你才想起，四月十五那夜，你答应了允礼去御园听他新校的曲子。那是他头一回主动约你，说曲子只吹一遍，“吹完了臣弟就回府，皇兄别嫌短”。\n\n允礼已经递了话进来，说笛子备好了，园子里的灯也让人挂上了。\n\n年羹尧那边，听说他把凯旋时穿的那副甲擦了三遍。\n\n苏培盛问，要不要派人去王府，说一声改日。","options":[{"id":"feast","label":"留在庆功宴上，与大将军对饮到底","effects":{"stability":2,"defense":1},"bonds":{"C03":{"trust":4,"safety":2}},"slight":"C05","reply":"庆功宴从申时摆到子时。最后那三杯酒，你与年羹尧对饮，满殿的将军都站起来喝彩。\n\n年羹尧喝完第三杯，把杯子倒扣在案上，眼眶红了：“皇上，西北那些弟兄，今夜都瞑目了。”\n\n散席时已过三更。苏培盛低声说，御园的灯，王爷让人亥时就撤了。"},{"id":"flute","label":"宴到一半离席，去御园赴约","effects":{"stability":-2},"bonds":{"C05":{"trust":4,"safety":2}},"slight":"C03","reply":"宴到戌时，你借口更衣，从偏殿出来，一路去了御园。\n\n允礼还在亭子里，笛子横在膝上，见你来了，愣了一下，随即笑开：“臣弟以为皇兄不来了。”\n\n他吹完那支新曲，你才回到宴上。最后的三杯酒，礼部临时改成了由亲王代饮。年羹尧什么也没说，照规矩谢了恩，只是那一夜，他再没往主座看一眼。"},{"id":"late","label":"宴席走完再赶去御园，他等多久算多久","effects":{"health":-3},"bonds":{"C03":{"trust":2},"C05":{"trust":1}},"slight":null,"reply":"庆功宴走完全程，你与年羹尧喝了那三杯酒。子时一过，你没回养心殿，直接去了御园。\n\n允礼还在。灯熄了大半，他裹着披风，靠着柱子打盹，听见脚步声，一下子坐直了。\n\n“皇兄……”\n\n他吹了那支曲子，吹得有点哑。你坐在夜风里听完，回去的路上咳了半宿。两边的人，都等到了你，也都等得太久了些。"}]},"K04":{"id":"K04","title":"城南的疫","kind":"dilemma","actor":"C04","location":"太医院","body":"七月里，城南几条胡同起了时疫。顺天府报上来，已经倒了几十户，坊间的郎中不够用，药铺的门槛被踏破了。\n\n温实初跪在殿下，请旨出宫。\n\n“臣想去城南。”他说，“臣在太医院十几年，看的都是贵人的脉。城南那些人，一辈子请不起一个太医。”\n\n你还没开口，他又补了一句，声音低了些：“臣知道，翊坤宫娘娘停香以后的调养，是臣在看；皇上入夏以来咳嗽，也是臣在看。臣若走了，这两处……臣不敢说别人能接得一样好。”\n\n他把头磕下去，没有再抬起来。他想去，你看得出来。他也知道你未必肯放。","options":[{"id":"go","label":"准他去城南，一个月为期","effects":{"people":3,"health":-2},"bonds":{"C04":{"trust":4,"safety":2}},"slight":"C07","reply":"温实初第二天一早就出了宫，只带了一个药童和两箱药。\n\n半个月后，顺天府奏报，城南的疫势压下去了，坊间都在传，宫里来了个不要诊金的太医。\n\n一个月后他回来，瘦了一圈，袖口磨破了，进殿的时候眼睛是亮的。\n\n只是这一个月里，翊坤宫换了两个太医，都不合年世兰的意。你自己的咳嗽，也拖到了秋天。"},{"id":"stay","label":"留他在宫里，城南另派人去","effects":{"health":2,"people":-1},"bonds":{"C07":{"trust":2}},"slight":"C04","reply":"你没有准。城南另派了太医院的两个医官和十车药材，你又从内库拨了银子。\n\n温实初领了旨，磕头谢恩，说话的声音很平。\n\n后来城南的疫也压下去了，只是慢了些，多走了几十户人家。温实初照常每日来请脉，照常叮嘱你亥时前歇。他什么也没说。你也没问。"},{"id":"split","label":"让卫临留宫，准他每隔三日回宫请脉","effects":{"treasury":-3,"people":1,"health":-1},"bonds":{"C04":{"trust":2}},"slight":null,"reply":"你让卫临留在宫里照看翊坤宫和你自己，准温实初去城南，只是每隔三日须回宫请一次脉。\n\n温实初磕头谢恩，第二天就出了宫。他在城南与宫里之间来回跑了一个月，每回进宫都带着一身药味，请完脉又匆匆出去。\n\n城南的疫压下去了。卫临头一回独当一面，也没出大错。只是这一个月的车马、药材、两头奔波，内库花了不少银子，温实初也累得够呛。"}]}};
export const REPAIR={"K01":{"C07":"年世兰听你说完，冷笑了一声：“皇上倒是记得来解释。”她把那盏鹊桥灯从柜子里取出来，灯纸已经有些黄了。“明年七夕，臣妾还扎。皇上若再不来，臣妾就把它烧了。”说完，她自己先笑了。","C06":"宜修听你说完，沉默了一会儿：“臣妾是皇后，七夕的规矩，臣妾自己领着办完了，没有失礼。”她顿了顿，“只是那夜的月亮很好，臣妾想，皇上若在，也会觉得好。”"},"K02":{"C07":"年世兰听你说起元宵那夜，别过脸去：“臣妾那日说的话，是不好听。可皇上就这样当着六宫……”她没说完，叹了口气，“罢了。安答应那支曲子，臣妾后来也听人说了，唱得是好。”","C08":"安陵容听你说完，低着头，过了很久才说：“臣妾那张纸条，写了三遍才敢递。”她抬起眼，眼眶是红的，“臣妾不怪皇上。臣妾只是想，下回再想要什么，还敢不敢开口。”你告诉她，敢。"},"K03":{"C05":"允礼听你说起那夜，摆了摆手：“皇兄是天子，庆功宴自然要紧。”他笑得很随意，却把笛子在手里转了两圈，“只是那支曲子，臣弟后来再也没吹过。皇兄若想听，得另约一回。这回，臣弟等皇兄先到。”","C03":"年羹尧听你说完，半晌才开口：“臣知道皇上有别的事。”他摸了摸袖口，“只是那三杯酒，臣在西北想了两年。”他抬起头，“下回臣回京，皇上补上。一杯都不能少。”"},"K04":{"C07":"年世兰听你说起温太医去城南的事，哼了一声：“皇上倒是心疼百姓。”她把药碗推开，“臣妾也是百姓的一个，夜里也睡不着。”可她到底还是把你带来的那包安神茶收下了。","C04":"温实初听你说完，跪着没起来：“臣明白皇上的难处。”过了一会儿，他才低声说，“城南后来又倒了二十几户。臣算过，若臣在，大约能救下一半。”他磕了个头，“臣说这个，不是怨皇上。是怕自己忘了。”"},"K05":{"C06":"宜修听你说完，沉默了很久：“那宫女是臣妾的人，臣妾认。只是皇上那日没让臣妾自己问，臣妾心里过不去。”她顿了顿，“如今皇上肯来说，臣妾便不再提了。”","C02":"苏培盛听你说起那十几夜，赶紧摆手：“奴才不委屈。皇后娘娘查得细，是好事。”可他说着说着，声音低了，“就是廊下夜里有点凉。”你说往后不会了。他笑了。"},"K06":{"C07":"年世兰听你说完，冷笑一声：“皇上倒是公正。”她转过身去，背对着你，过了很久才说：“他那折子，臣妾后来也看了。是他自己要的。臣妾不怪皇上了，臣妾怪他。”","C03":"年羹尧听你说完，摇了摇头：“皇上是心疼臣妹，臣知道。”他抬起头，“可皇上那道旨意，让臣在西北的弟兄们面前，抬不起头。臣宁可挨罚。”你说下回不会了。他说：“那就好。”"},"K07":{"C06":"宜修听你说完，把那本出入簿推到你面前：“这本子臣妾一直留着。皇上要是觉得臣妾管得多了，臣妾就不管了。”你说她管得对。她看了你很久，才把簿子收回去。","C05":"允礼听你说完，摆摆手：“登记就登记，臣弟的字好看，皇后娘娘翻着也赏心悦目。”他笑完了，又轻声补一句，“只是臣弟往后，还能常来么？”你说能。"},"K08":{"C03":"年羹尧回京述职，听你说完，半晌没说话。后来他说：“臣在西北这几年，想明白一件事。皇上留臣，不是不心疼臣，是更心疼那些守边的兵。”他笑了笑，“臣也心疼。”"},"K09":{"C02":"苏培盛听你说完，眼眶红了：“皇上，奴才没怨过。能多伺候皇上一年，是奴才的福气。”他顿了顿，又小声说，“就是腿疼的时候，会想一想歇着是什么滋味。”"}};
